INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('disciplina-positiva', 0, '¿Qué es el "efecto de sobrejustificación" en el contexto de la motivación?', '["El fenómeno por el cual dar un premio aumenta el interés genuino de una persona por una actividad, porque la asocia con algo agradable y la repite con más ganas","El fenómeno por el cual premiar con algo externo una actividad que ya se disfrutaba genuinamente puede reducir el interés intrínseco, porque el cerebro reinterpreta la razón de hacerlo como \"por el premio\" en vez de \"porque me gusta\"","El fenómeno por el cual un estudiante justifica su mala conducta con explicaciones cada vez más largas para evitar la consecuencia que le corresponde","El fenómeno por el cual explicar demasiado una norma hace que los estudiantes la cumplan menos, porque la perciben como negociable y discutible"]'::jsonb, 1, 'Este efecto, documentado en la investigación de motivación de Deci y Ryan, muestra que introducir recompensas externas para una conducta que ya tenía motivación intrínseca puede debilitar esa motivación genuina, un hallazgo contraintuitivo pero bien establecido.', 'lesson'),
('disciplina-positiva', 1, '¿En qué situación un sistema de refuerzo externo (puntos, premios) puede ser útil según este curso?', '["Como estrategia permanente del aula, porque mantiene la conducta estable durante todo el año","Como apoyo temporal para ayudar a iniciar un hábito nuevo y difícil, con la intención de retirarlo gradualmente a medida que la conducta se vuelve más natural","Como consecuencia para el grupo cuando la conducta empeora, quitando puntos acumulados","Como forma de motivar a los estudiantes con bajo rendimiento, que no responden a otras estrategias"]'::jsonb, 1, 'Un refuerzo externo puede servir como "andamio temporal" para iniciar una conducta nueva, siempre que el objetivo final sea que la motivación se vuelva intrínseca y el refuerzo externo deje de ser necesario.', 'lesson'),
('disciplina-positiva', 2, '¿Cuáles son los tres pilares de la motivación intrínseca según la teoría de la autodeterminación (Deci y Ryan)?', '["Recompensa, reconocimiento y calificación","Autonomía, competencia y conexión","Disciplina, constancia y orden","Interés, talento y esfuerzo"]'::jsonb, 1, 'La teoría de la autodeterminación identifica autonomía (sentir control sobre las propias decisiones), competencia (sentir progreso real) y conexión (pertenencia y relación) como los tres pilares que sostienen la motivación genuina y duradera.', 'lesson'),
('disciplina-positiva', 3, '¿Por qué la retroalimentación sobre el PROCESO ("mejoraste en cómo organizas tus ideas") es más motivadora que solo calificar el resultado final?', '["Porque los estudiantes prefieren los comentarios a las notas, aunque el efecto en la motivación sea el mismo","Porque hace visible el progreso del estudiante, fortaleciendo el pilar de \"competencia\" (sentir que se está mejorando), algo que una calificación final por sí sola no comunica","Porque es más rápida de dar que una calificación tradicional","Porque sirve sobre todo a estudiantes de bajo rendimiento, que necesitan más ánimo que los demás para no rendirse"]'::jsonb, 1, 'La retroalimentación de proceso hace visible el progreso —el pilar de "competencia" de la motivación intrínseca— de una forma que una calificación final aislada no logra comunicar, ya que esta última no muestra la trayectoria de mejora.', 'lesson'),
('disciplina-positiva', 4, 'Según la disciplina positiva, ¿qué significa ser "firme y amable al mismo tiempo"?', '["Ser firme algunos días y amable otros, según lo que pida cada situación del grupo","Mantener límites claros y consistentes (firmeza) junto con respeto y calidez genuina (amabilidad) de forma simultánea, sin sacrificar ninguna de las dos","Ser principalmente amable y aplicar firmeza solo en casos graves, para cuidar la relación con el estudiante","Ser firme con las normas y dejar la amabilidad para los momentos fuera de clase"]'::jsonb, 1, 'La disciplina positiva propone que firmeza y amabilidad no son opuestos que requieren balance: pueden y deben estar presentes al mismo tiempo. Un límite claro dicho con calidez es más efectivo que uno impuesto con frialdad o uno diluido por exceso de permisividad.', 'lesson'),
('disciplina-positiva', 5, '¿Por qué involucrar al estudiante en proponer la solución ("¿qué crees que podrías hacer para reparar esto?") genera mayor compromiso que simplemente imponer una consecuencia?', '["Porque el estudiante suele proponer una consecuencia más dura que la del docente, y así la acepta mejor","Porque convierte al estudiante de receptor pasivo de un castigo a participante activo en la solución, lo cual fortalece su compromiso genuino con el cambio de conducta","Porque así la consecuencia resulta más leve y el estudiante no se resiente con el docente","Porque así el docente no tiene que decidir la consecuencia y evita conflictos con la familia"]'::jsonb, 1, 'La participación activa en construir la solución aumenta el sentido de responsabilidad y compromiso del estudiante, comparado con recibir pasivamente una consecuencia decidida completamente por otra persona.', 'lesson'),
('disciplina-positiva', 6, '¿Por qué reconocer específicamente el esfuerzo y la estrategia ("seguiste intentando distintas formas hasta encontrar una que funcionó") es más efectivo a largo plazo que elogiar solo el resultado final?', '["Porque el estudiante se siente más reconocido, aunque a largo plazo el efecto sea el mismo que elogiar el resultado","Porque enseña que el valor está en el proceso de aprender, sosteniendo la motivación incluso cuando el resultado no es perfecto — una mentalidad de crecimiento que favorece la persistencia","Porque elogiar el resultado final es contraproducente y conviene evitarlo en cualquier caso","Porque funciona sobre todo con estudiantes que ya tienen buen rendimiento y buscan mejorar"]'::jsonb, 1, 'Reconocer el proceso y el esfuerzo, en vez de solo el resultado, refuerza una mentalidad de crecimiento (Carol Dweck) que sostiene la motivación y la persistencia del estudiante incluso ante resultados imperfectos, algo que el elogio centrado solo en el resultado no logra.', 'lesson'),
('disciplina-positiva', 7, '¿Cómo se conecta este curso de Disciplina Positiva con los otros cursos de la ruta Clima y Convivencia Escolar?', '["No tiene una relación directa: cada curso de la ruta aborda un tema distinto y conviene aplicarlos por separado, empezando por el que resuelva el problema más urgente del grupo","Entender la conducta desafiante se sostiene con inteligencia emocional (SEL), se comunica con asertividad, y se motiva desde adentro con disciplina positiva — los cuatro elementos trabajan juntos para construir el clima de aula","Disciplina positiva es la base y los otros cursos son complementos opcionales que se aplican después","Manejo de Conductas es el central; los demás sirven si sobra tiempo en el año"]'::jsonb, 1, 'Los cursos de esta ruta están diseñados para complementarse: comprender la conducta, desarrollar inteligencia emocional, comunicar con asertividad y motivar desde la disciplina positiva son piezas interconectadas de un mismo enfoque integral del clima de aula.', 'lesson'),
('disciplina-positiva', 8, 'Una docente tiene un sistema de estrellas que funcionó un mes y ahora los estudiantes piden más premios para participar. ¿Qué fenómeno ocurre?', '["Fatiga y sobrejustificación: el premio externo reemplaza la motivación por la tarea.","Mejora de la motivación intrínseca, porque el premio hace más atractiva la tarea que antes aburría.","Falta de claridad en las normas.","Exceso de autonomía del grupo."]'::jsonb, 0, 'La sobrejustificación reduce el interés propio por la actividad.', 'exam'),
('disciplina-positiva', 9, 'Un docente quiere dar un reconocimiento. ¿Cuál tiene menos riesgo de dañar la motivación intrínseca?', '["Un premio prometido por cada tarea completada, que el estudiante conoce desde el inicio de la semana.","Una estrella por responder rápido.","Un ranking semanal de los mejores.","Un reconocimiento inesperado y específico por el esfuerzo realizado."]'::jsonb, 3, 'El premio sorpresa tiene menos riesgo que el prometido.', 'exam'),
('disciplina-positiva', 10, 'Una docente ofrece ''elige entre hacer el ejercicio 1 o el ejercicio 2'', que son idénticos. ¿Qué crítica aplica del curso?', '["Es la mejor forma de dar autonomía.","Es innecesaria porque los estudiantes no pueden elegir con criterio y el docente debe decidir todo.","Es una elección falsa; la autonomía real exige opciones significativas dentro de límites.","Es adecuada para grupos que todavía no saben elegir."]'::jsonb, 2, 'Autonomía real vs. elección falsa.', 'exam'),
('disciplina-positiva', 11, 'Un estudiante se niega a hacer la tarea. ¿Qué respuesta combina firmeza y amabilidad?', '["''Si no la haces, te bajo puntos.''","''Entiendo que hoy no tienes ganas. La tarea es parte de la clase; ¿cómo empezamos?''","''Está bien, hoy descansa y mañana la recuperas.''","''Hoy no te obligo, pero mañana harás el doble en el recreo.''"]'::jsonb, 1, 'Firme y amable: límite claro y respeto.', 'exam'),
('disciplina-positiva', 12, 'Un docente piensa que la disciplina positiva significa no poner límites. ¿Qué aclaración corresponde?', '["Se mantienen límites claros y consecuencias lógicas, con respeto y diálogo.","Tiene razón; se evitan los límites para que el estudiante no se sienta controlado.","Tiene razón en parte: se ponen límites solo cuando hay una falta grave.","Que los límites los pone el grupo y el docente solo los acompaña."]'::jsonb, 0, 'No es permisividad.', 'exam'),
('disciplina-positiva', 13, 'Una clase tiene un problema recurrente: el desorden al guardar materiales. ¿Qué estrategia favorece la responsabilidad?', '["Una nota de conducta colectiva en el cuaderno hasta que el desorden termine.","Quitar cinco minutos de recreo al grupo cada vez que pase.","Nombrar un encargado fijo para guardar el material.","Una reunión de clase para que el grupo proponga y acuerde soluciones."]'::jsonb, 3, 'Involucrar al grupo en la solución.', 'exam'),
('disciplina-positiva', 14, 'Al final de la semana, una docente quiere reforzar la identidad positiva de un estudiante inseguro. ¿Qué comentario es más útil?', '["''Noté que intentaste otra estrategia cuando se complicó; eso muestra perseverancia.''","''Eres muy inteligente.''","''Bien, sigue así.''","''Mejor que ayer, pero aún falta mucho para que puedas compararte con tus compañeros.''"]'::jsonb, 0, 'Celebrar el proceso y el esfuerzo.', 'exam'),
('disciplina-positiva', 15, '¿Por qué los sistemas de puntos o estrellas suelen perder efecto con el tiempo?', '["Porque se habitúan y necesitan premios cada vez mayores para el mismo efecto","Porque son difíciles de administrar en grupos grandes","Porque las familias terminan oponiéndose a ellos","Porque funcionan sobre todo con estudiantes mayores, que entienden mejor el valor de los premios"]'::jsonb, 0, 'Es la fatiga de los sistemas de premios: el estímulo pierde fuerza y la conducta depende de premios crecientes.', 'exam'),
('disciplina-positiva', 16, '¿Qué es el efecto de sobrejustificación?', '["Que explicar demasiado una norma la vuelve confusa","Que premiar con algo externo una actividad que ya se disfrutaba puede reducir la motivación por ella","Que los estudiantes buscan justificar su mala conducta con explicaciones cada vez más largas y excusas","Que las notas altas motivan más que las bajas"]'::jsonb, 1, 'Cuando la actividad pasa a hacerse ''por el premio'', la motivación propia puede disminuir al retirarlo.', 'exam'),
('disciplina-positiva', 17, '¿Cuándo puede ser útil un refuerzo externo, según el curso?', '["Como base permanente de la motivación del aula durante todo el año","De forma temporal, para iniciar un hábito nuevo y difícil, retirándolo poco a poco","Para premiar a los estudiantes con mejor rendimiento del grupo","Cuando el grupo entero se porta mal y hace falta recuperar el orden"]'::jsonb, 1, 'Un refuerzo externo puede ayudar a arrancar un hábito; el objetivo es retirarlo gradualmente.', 'exam'),
('disciplina-positiva', 18, '¿Qué diferencia hay entre un premio sorpresa y un premio prometido?', '["Ninguna: ambos tienen el mismo efecto","El reconocimiento inesperado daña menos la motivación que el premio prometido","El premio prometido motiva más porque el estudiante sabe desde el inicio qué va a obtener","El premio sorpresa funciona mejor con adolescentes"]'::jsonb, 1, 'La investigación muestra que el ''si haces esto, te doy aquello'' es el que más tiende a desplazar la motivación propia.', 'exam'),
('disciplina-positiva', 19, '¿Cuáles son los tres pilares de la motivación intrínseca que trabaja el curso?', '["Recompensa, reconocimiento y calificación","Autonomía, competencia y conexión","Orden, constancia y puntualidad","Interés, talento y esfuerzo"]'::jsonb, 1, 'Sentir cierta elección, notar el propio progreso y sentirse parte del grupo sostienen la motivación propia.', 'exam'),
('disciplina-positiva', 20, '¿Qué cuarto factor de motivación agrega el curso a los tres pilares?', '["La competencia entre estudiantes por ver quién saca la mejor nota","El propósito: entender para qué sirve lo que se aprende","El miedo a reprobar","La recompensa al final del periodo"]'::jsonb, 1, 'Muchos estudiantes se motivan más cuando ven la utilidad de lo que aprenden, más allá de la nota.', 'exam'),
('disciplina-positiva', 21, '¿Qué malentendido común sobre la disciplina positiva aclara el curso?', '["Que exige levantar la voz para poner límites cuando el grupo no responde","Que significa permisividad: en realidad mantiene límites claros y consecuencias, con amabilidad","Que solo funciona en primaria, cuando los estudiantes son más pequeños","Que reemplaza la necesidad de tener normas y consecuencias en el aula"]'::jsonb, 1, 'La disciplina positiva es firme y amable a la vez; no elimina las consecuencias ni los límites.', 'exam'),
('disciplina-positiva', 22, 'Hay desorden constante en las transiciones y afecta a todo el grupo. ¿Qué herramienta de disciplina positiva conviene?', '["Una reunión breve de clase para buscar soluciones juntos","Una consecuencia colectiva para que todos aprendan a la vez","Un sistema de puntos por grupo que premie al que se organice mejor","Cambiar la distribución del aula sin consultar al grupo"]'::jsonb, 0, 'Cuando el problema es colectivo, involucrar al grupo en la solución aumenta el compromiso con ella.', 'exam'),
('disciplina-positiva', 23, '¿Qué frase construye una identidad positiva y duradera en un estudiante?', '["''Eres el más inteligente de toda la clase.''","''Eres alguien que persiste hasta lograrlo.''","''Por fin hiciste algo bien.''","''Si sigues así toda la semana, te voy a dar un premio.''"]'::jsonb, 1, 'Describir una cualidad que el estudiante puede seguir practicando (persistir, ayudar) fortalece una identidad positiva, a diferencia de etiquetas de talento fijo.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('bienestar-docente', 0, '¿Cuáles son los tres componentes que definen el síndrome de burnout (desgaste profesional)?', '["Cansancio físico, dolor de cabeza frecuente y falta de sueño acumulada durante el año escolar","Agotamiento emocional, despersonalización (distanciamiento cínico) y baja realización personal (sensación de que el trabajo ya no tiene sentido)","Falta de vacaciones, exceso de reuniones y bajo salario","Estrés, ansiedad y tristeza, que aparecen en momentos de mucha carga de trabajo"]'::jsonb, 1, 'El burnout, como síndrome reconocido en la literatura de salud ocupacional, se compone específicamente de estos tres elementos: agotamiento emocional, despersonalización y baja realización personal — no es simplemente sinónimo de estar cansado.', 'lesson'),
('bienestar-docente', 1, '¿Por qué es importante reconocer las señales TEMPRANAS de desgaste docente (dormir mal, irritabilidad nueva, perder disfrute en actividades que antes gustaban)?', '["Porque permite pedir una licencia a tiempo, antes de que el problema afecte la evaluación anual del docente","Porque permite intervenir a tiempo, antes de llegar a un agotamiento más severo y difícil de revertir","Porque sirven para justificar ausencias laborales ante la dirección","Porque indican que hace falta tomar vacaciones de inmediato"]'::jsonb, 1, 'El burnout se desarrolla gradualmente, y las señales tempranas —a menudo sutiles— ofrecen una ventana de oportunidad para intervenir con estrategias de autocuidado antes de que el desgaste se vuelva más severo y complejo de revertir.', 'lesson'),
('bienestar-docente', 2, '¿Por qué separar conscientemente "lo que está en mi control" de "lo que no está en mi control" ayuda a reducir el agotamiento emocional docente?', '["Porque permite concentrar todo el esfuerzo en lo que sí se puede cambiar, trabajando más horas en eso","Porque gran parte del desgaste viene de intentar controlar lo que está fuera de tu alcance; soltarlo reduce la carga mental","Porque significa dejar de esforzarse en el trabajo diario","Porque traslada la responsabilidad del desgaste a la dirección y a las familias, y así el docente deja de preocuparse por lo que ocurre en su aula"]'::jsonb, 1, 'Identificar la diferencia entre lo controlable y lo no controlable, y practicar soltar activamente esto último, es una estrategia de regulación emocional documentada que reduce la carga mental innecesaria asociada con el desgaste profesional.', 'lesson'),
('bienestar-docente', 3, '¿Cómo contribuye el perfeccionismo al desgaste docente, según este curso?', '["El perfeccionismo mejora el desempeño docente, y el desgaste es un costo razonable a cambio de clases de mayor calidad","La creencia de que cada clase debe salir perfecta genera una fuente constante de desgaste innecesario; aceptar que \"suficientemente bien\" es suficiente libera energía emocional para la sostenibilidad a largo plazo","El perfeccionismo afecta sobre todo a los docentes nuevos; con los años se aprende a sostenerlo sin un costo emocional importante","No hay una relación directa: el desgaste viene de la carga de trabajo, no de la forma de pensar del docente"]'::jsonb, 1, 'La exigencia de perfección constante consume energía emocional de forma desproporcionada. Reconocer que un desempeño "suficientemente bueno" es válido y suficiente es una estrategia clave para sostener el bienestar docente a largo plazo.', 'lesson'),
('bienestar-docente', 4, '¿Por qué "separar tu identidad de los resultados de estudiantes específicos" es importante para el bienestar docente?', '["Porque significa que no debe importarte el progreso de tus estudiantes","Porque cargar tu propio valor como docente completamente sobre el desempeño de cada estudiante individual, especialmente en circunstancias fuera de tu control, es una fuente de desgaste emocional insostenible","Porque el resultado de cada estudiante depende sobre todo de su familia, y el docente no puede influir mucho en él","Porque así se puede evaluar la propia práctica solo con el promedio del grupo, sin mirar casos individuales que distorsionan"]'::jsonb, 1, 'Esforzarte genuinamente por tus estudiantes es distinto de cargar tu autoestima profesional completamente sobre resultados que dependen de múltiples factores fuera de tu control — esta distinción protege tu bienestar sin reducir tu compromiso real.', 'lesson'),
('bienestar-docente', 5, '¿Por qué pedir ayuda (a colegas, dirección, o apoyo profesional) se considera una práctica profesional reconocida y no una debilidad?', '["Porque mostrar que se pide ayuda mejora la imagen del docente ante la dirección","Porque reduce el riesgo de desgaste severo y ayuda a sostenerse en la profesión, como cualquier derivación responsable","Porque los docentes nuevos necesitan ayuda; los experimentados deberían resolver solos y acudir a otros solo en casos excepcionales","Porque es válido en casos de crisis extrema, cuando ya no se puede seguir trabajando"]'::jsonb, 1, 'Buscar apoyo —de colegas o profesional— es una estrategia de sostenibilidad reconocida, equivalente a la misma lógica de derivación responsable que un docente aplicaría con un estudiante que enfrenta una situación que requiere apoyo especializado.', 'lesson'),
('bienestar-docente', 6, '¿Por qué es valioso que un docente reconozca sus propios logros profesionales, no solo los de sus estudiantes?', '["Porque así el docente puede mostrar sus logros en la evaluación de desempeño anual","Porque es común que los docentes celebren constantemente el progreso ajeno sin reconocer su propio crecimiento profesional, y hacerlo es parte de sostener el bienestar a largo plazo","Porque los logros de los estudiantes dependen poco del trabajo del docente","Porque los docentes con más años de experiencia acumulan logros que conviene documentar"]'::jsonb, 1, 'Reconocer el propio crecimiento y logros profesionales —no solo los de los estudiantes— es una práctica de autocuidado que contribuye a sostener la motivación y el bienestar del docente a lo largo de una carrera larga.', 'lesson'),
('bienestar-docente', 7, 'Al cerrar la ruta completa de Clima y Convivencia Escolar (5 cursos), ¿cuál es la idea central que los conecta a todos?', '["La disciplina positiva es la base y los demás cursos la complementan","Entender la conducta, la inteligencia emocional, la asertividad, la motivación interna y el propio bienestar funcionan como un sistema que, sostenido en el tiempo, construye un buen clima de aula","Cada curso funciona de forma aislada: lo más eficaz es elegir el que resuelva el problema más visible del grupo y aplicarlo con firmeza, dejando para después el bienestar docente, que es secundario frente a la disciplina","La disciplina estricta es más importante que cualquier otro elemento de la ruta"]'::jsonb, 1, 'Los cinco cursos de esta ruta no son piezas aisladas: forman un sistema donde comprensión de la conducta, inteligencia emocional, comunicación, motivación y bienestar docente se refuerzan mutuamente para sostener un clima de aula positivo de forma duradera, no solo puntual.', 'lesson'),
('bienestar-docente', 8, 'Una docente duerme mal, se irrita con facilidad con sus estudiantes y siente que su trabajo ya no tiene sentido. ¿Qué componentes del burnout se reflejan?', '["Cansancio físico por exceso de trabajo, sin ningún impacto emocional importante.","Agotamiento emocional, despersonalización y baja realización personal.","Estrés normal previo a una evaluación.","Falta de vocación para la docencia."]'::jsonb, 1, 'El burnout implica los tres componentes.', 'exam'),
('bienestar-docente', 9, 'Una maestra siente estrés fuerte antes de la supervisión y se recupera al terminar. ¿Cómo se distingue de burnout?', '["Es burnout, porque hay estrés intenso.","Es burnout leve, porque el estrés intenso siempre es el inicio del desgaste.","Es estrés situacional que cede tras el evento; el burnout es persistente.","Es ansiedad que requiere tratamiento."]'::jsonb, 2, 'Estrés normal vs. burnout.', 'exam'),
('bienestar-docente', 10, 'Un docente revisa mensajes del grupo de trabajo a las 10 de la noche todos los días. ¿Qué límite sugiere el curso?', '["Responder más rápido para no generar quejas.","Definir un horario de cierre y avisar a la comunidad cuándo responderá.","Apagar el celular sin avisar.","Dejar de usar mensajería por completo."]'::jsonb, 1, 'Límites con la tecnología fuera de horario.', 'exam'),
('bienestar-docente', 11, 'Una docente se siente culpable por decir que no a una comisión adicional. ¿Qué mensaje del curso aplica?', '["Debe aceptar todo lo que le pidan para ser considerada una buena docente comprometida.","Decir que no puede ayudarla a sostener su trabajo; no es falta de compromiso.","Debe aceptar esta vez y negarse la próxima.","Debe aceptar y quejarse con colegas."]'::jsonb, 1, 'El mito del buen docente que lo sacrifica todo.', 'exam'),
('bienestar-docente', 12, 'Un docente lleva semanas con insomnio, tristeza y poca energía que afectan su trabajo. ¿Qué corresponde?', '["Esperar a las vacaciones.","Aumentar su carga para distraerse.","Callarlo para no preocupar a nadie.","Buscar apoyo profesional de salud mental y compartirlo con alguien de confianza."]'::jsonb, 3, 'Pedir ayuda no es debilidad.', 'exam'),
('bienestar-docente', 13, 'Una maestra tarda cada día en desconectarse del trabajo. ¿Qué práctica breve propone el curso?', '["Revisar el correo antes de dormir.","Planificar toda la semana el domingo.","Quedarse más tiempo para dejar todo listo antes de irse.","Un ritual de cierre de jornada, como anotar lo logrado y lo pendiente para mañana."]'::jsonb, 3, 'Ritual de cierre.', 'exam'),
('bienestar-docente', 14, 'Una docente quiere sostener su bienestar durante el año escolar. ¿Qué estrategia es más realista?', '["Esperar a las vacaciones para recuperarse.","Tomarse un fin de semana libre cuando se sienta muy agotada.","Concentrar el trabajo en semanas intensas para tener otras más tranquilas.","Planificar pequeños descansos y rituales a lo largo del año, sin esperar a las vacaciones largas."]'::jsonb, 3, 'Planificar descansos reales.', 'exam'),
('bienestar-docente', 15, '¿Cuál de estas es una señal temprana de desgaste, antes de que sea grave?', '["Sentir nervios el día de una evaluación importante","Dormir mal aunque estés cansado y perder el disfrute de actividades que antes te gustaban","Tener un día difícil aislado","Sentir cansancio después de una jornada larga que se recupera con una buena noche de descanso"]'::jsonb, 1, 'El burnout empieza con señales sutiles y persistentes (sueño, irritabilidad, pérdida del disfrute), no con un día difícil aislado.', 'exam'),
('bienestar-docente', 16, '¿Por qué la docencia se considera una profesión de alto riesgo emocional?', '["Porque los docentes trabajan muchas horas fuera del horario, planificando y calificando","Porque exige regulación emocional constante y cientos de decisiones al día","Porque los salarios no reflejan la carga de trabajo","Porque el trabajo es repetitivo y poco variado"]'::jsonb, 1, 'La exposición emocional continua y la carga de decisiones hacen que el desgaste sea un riesgo propio de la profesión.', 'exam'),
('bienestar-docente', 17, '¿Por qué el burnout de un docente también afecta a sus estudiantes?', '["Los afecta poco: el docente suele separar bien su estado de su trabajo","Porque reduce la paciencia, la capacidad de co-regulación y la energía creativa en la enseñanza","Porque los estudiantes se contagian del cansancio físico del docente y rinden menos en las evaluaciones del periodo","Porque el docente deja de corregir tareas"]'::jsonb, 1, 'Un docente agotado tiene menos recursos emocionales para sostener el clima del aula.', 'exam'),
('bienestar-docente', 18, '¿Qué técnica rápida de regulación puede usarse entre una clase y otra?', '["Revisar los mensajes del grupo de padres","Una respiración consciente de 30 segundos o tomar un vaso de agua con calma","Aprovechar para planificar a toda prisa la clase siguiente y revisar pendientes","Revisar rápido las tareas pendientes de corrección"]'::jsonb, 1, 'No hace falta una hora libre: pausas breves y conscientes ayudan a regularse durante la jornada.', 'exam'),
('bienestar-docente', 19, '¿Para qué sirve un ritual de cierre de la jornada laboral?', '["Para seguir trabajando desde casa con más energía","Para marcar un límite entre trabajo y vida personal, como anotar tres cosas que salieron bien","Para revisar todos los correos pendientes","Para planificar toda la semana siguiente"]'::jsonb, 1, 'Un gesto consciente al terminar el día ayuda a cerrar mentalmente la jornada y recuperarse.', 'exam'),
('bienestar-docente', 20, '¿Qué dice el curso sobre el sueño y la regulación emocional?', '["Que se puede compensar dormir mal con técnicas de respiración durante el día","Que ninguna técnica compensa por completo la falta crónica de sueño","Que el sueño influye en la energía, pero no en la paciencia","Que basta con recuperar sueño el fin de semana"]'::jsonb, 1, 'Dormir mal reduce directamente la paciencia y la regulación; es la base de las demás estrategias.', 'exam'),
('bienestar-docente', 21, '¿Cuándo conviene buscar apoyo profesional por desgaste?', '["Cuando ya no puedes ir a trabajar","Si las señales persisten semanas, afectan tu sueño o salud, o ya no puedes sostener el trabajo","Después de las vacaciones, si el cansancio sigue","Cuando la dirección lo sugiera"]'::jsonb, 1, 'Pedir ayuda profesional cuando las señales persisten es una decisión responsable, no una señal de debilidad.', 'exam'),
('bienestar-docente', 22, '¿Qué es comunicar límites de forma proactiva?', '["Esperar a sentirte desbordado para decir que no","Avisar con anticipación tu horario real de disponibilidad a la dirección, colegas y familias","Responder todos los mensajes al instante, a cualquier hora, para evitar conflictos con las familias","Responder solo los mensajes urgentes en cuanto lleguen"]'::jsonb, 1, 'Anticipar los límites evita conflictos y reduce la presión de estar disponible siempre.', 'exam'),
('bienestar-docente', 23, '¿Por qué conviene planificar pequeños descansos durante el año escolar?', '["Porque las vacaciones largas nunca alcanzan para recuperarse del desgaste de todo el año","Porque esperar solo a las vacaciones deja meses sin ningún punto de recuperación real","Porque así se trabaja menos horas en total","Porque así se evita pedir días de licencia"]'::jsonb, 1, 'Distribuir momentos de recuperación a lo largo del año sostiene la energía mejor que esperar a las vacaciones.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('educacion-inclusiva', 0, '¿Cuál es la diferencia principal entre una "adaptación" y una "modificación" curricular?', '["La adaptación cambia lo que se espera aprender; la modificación cambia cómo se accede al contenido","La adaptación cambia cómo el estudiante accede al mismo contenido y objetivo; la modificación cambia qué se espera que aprenda","La modificación es más inclusiva porque se ajusta mejor al estudiante","Las adaptaciones son para discapacidad física y las modificaciones para intelectual"]'::jsonb, 1, 'La adaptación mantiene la misma meta de aprendizaje pero cambia el camino de acceso (más tiempo, otro formato de respuesta). La modificación cambia la meta misma (menos contenido, objetivos más simples). Confundirlas puede llevar a bajar expectativas cuando en realidad solo hacía falta un ajuste de acceso.', 'lesson'),
('educacion-inclusiva', 1, 'Un estudiante con TEA tiene una reacción fuerte cuando suena la alarma de incendios sin aviso previo. ¿Cuál es la estrategia más adecuada para la próxima vez?', '["No hacer nada especial, porque el simulacro debe ser igual para todos","Avisarle al estudiante con anticipación cuando sea posible, y considerar que la reacción es una respuesta sensorial real, no \"mal comportamiento\"","Exponerlo a la alarma sin aviso varias veces para que se habitúe","Sacarlo del aula de forma permanente durante los simulacros"]'::jsonb, 1, 'La sensibilidad sensorial en el TEA es real, no una elección. Avisar con anticipación cuando sea posible, y entender la reacción como respuesta a un estímulo genuinamente abrumador —no como desobediencia—, es la base de un acompañamiento respetuoso y efectivo.', 'lesson'),
('educacion-inclusiva', 2, '¿Por qué es importante variar la FORMA de repetir un concepto (dibujo, objeto real, pregunta práctica) en vez de repetir literalmente la misma frase varias veces con un estudiante con síndrome de Down?', '["Porque así la clase es más entretenida para todo el grupo, aunque el efecto en el aprendizaje sea el mismo","Porque variar la forma ayuda a que el concepto se consolide, en vez de quedarse en una repetición mecánica","Porque repetir la misma frase muchas veces genera rechazo y aburrimiento en el estudiante, sin importar el tema","Porque así se atiende el estilo de aprendizaje de cada estudiante"]'::jsonb, 1, 'La repetición mecánica de la misma frase tiende a quedarse superficial. Presentar el mismo concepto desde ángulos distintos (visual, concreto, práctico) ayuda a construir una comprensión más sólida y duradera, especialmente cuando el aprendizaje abstracto directo es más difícil.', 'lesson'),
('educacion-inclusiva', 3, '¿Por qué dividir una instrucción larga en pasos cortos y verificar uno a la vez ayuda específicamente a un estudiante con TDAH?', '["Porque los estudiantes con TDAH no pueden escuchar instrucciones largas en absoluto","Porque una instrucción con varios pasos encadenados sobrecarga la memoria de trabajo antes de llegar al último paso, y dividirla reduce esa carga cognitiva","Porque es una regla general que no tiene relación con el TDAH específicamente","Porque así el estudiante termina la tarea más rápido"]'::jsonb, 1, 'El TDAH afecta la memoria de trabajo y la capacidad de sostener varios pasos en mente a la vez. Dividir instrucciones y verificar paso a paso reduce esa carga cognitiva, aumentando la probabilidad real de que la tarea se complete correctamente.', 'lesson'),
('educacion-inclusiva', 4, '¿Por qué el término "mudo" describe mal a la mayoría de estudiantes sin lenguaje oral?', '["Porque ningún estudiante sin lenguaje oral puede comunicarse de ninguna forma","Porque la mayoría sí se comunica, aunque no con la voz (tableros, pictogramas, señas o tecnología)","Porque es un término técnico correcto, aunque suena ofensivo","Porque es un término que solo aplica a estudiantes sordos; en los demás casos se dice \"no verbal\" para indicar que no se comunican"]'::jsonb, 1, 'El término "mudo" implica ausencia total de comunicación, cuando en realidad la mayoría de estudiantes sin lenguaje oral se comunican activamente mediante Comunicación Aumentativa y Alternativa. Presumir competencia y dirigirse directamente al estudiante, en vez de asumir que no puede comunicarse, es la base de un trato respetuoso y efectivo.', 'lesson'),
('educacion-inclusiva', 5, 'Una escuela admite a un estudiante con discapacidad, pero lo sienta al fondo y le da actividades distintas al grupo. ¿Es educación inclusiva?', '["No: incluir implica participar y aprender con el grupo, con los apoyos necesarios.","Sí, porque está presente en el aula regular.","Sí, porque recibe atención individual adaptada a su nivel.","Depende de lo que la familia haya acordado con la escuela."]'::jsonb, 0, 'La inclusión no es solo presencia física.', 'exam'),
('educacion-inclusiva', 6, 'Una docente quiere referirse a un estudiante con discapacidad en una reunión. ¿Qué expresión es más adecuada?', '["''El sordito del salón''.","''Estudiante con discapacidad auditiva'', centrando la persona antes que la condición.","''El discapacitado de 4.º'', porque es la expresión más corta y la que todos entienden en la reunión.","''El niño con problemas''."]'::jsonb, 1, 'El lenguaje importa: personas primero y términos respetuosos.', 'exam'),
('educacion-inclusiva', 7, 'Una docente planifica una clase con una lectura, un video con subtítulos y un cartel; los estudiantes eligen cómo demostrar lo aprendido. ¿Qué principio aplica?', '["Adaptación individual que se prepara después de la clase para cada estudiante que lo necesite, según su diagnóstico.","Modificación de los objetivos para todos.","Diferenciación por niveles: cada grupo trabaja una versión distinta.","Diseño Universal para el Aprendizaje: múltiples formas de representación, acción y expresión y motivación."]'::jsonb, 3, 'DUA diseña desde el inicio para la variabilidad.', 'exam'),
('educacion-inclusiva', 8, 'Un estudiante recibe más tiempo para leer y un texto ampliado, pero evalúan los mismos objetivos que al grupo. ¿Qué es?', '["Una modificación de objetivos.","Una modificación: el estudiante tiene objetivos de aprendizaje distintos y más bajos que el grupo.","Un refuerzo escolar fuera del horario de clase.","Una adaptación: cambia cómo accede al aprendizaje, no qué se espera aprender."]'::jsonb, 3, 'Adaptación vs. modificación.', 'exam'),
('educacion-inclusiva', 9, 'Un estudiante con TEA se altera con el timbre fuerte y el ruido del recreo. ¿Qué apoyo es más pertinente?', '["Pedirle que participe en el recreo sin cambios para que se acostumbre al ruido con el tiempo.","Dejarlo en el aula durante todo el recreo.","Anticipar los momentos ruidosos con apoyos visuales y ofrecer una opción de protección sensorial, como un espacio tranquilo.","Explicarle que el ruido es normal y que no debe asustarse."]'::jsonb, 2, 'Sensibilidad sensorial y previsibilidad.', 'exam'),
('educacion-inclusiva', 10, 'Un docente de Down pide una respuesta a un estudiante y, al ver que tarda, la completa él mismo. ¿Qué habría sido mejor?', '["Evitar preguntarle para no incomodarlo.","Dar tiempo adicional de procesamiento y repetir la pregunta de forma sencilla.","Pedir que otro conteste por él.","Cambiar la pregunta por una trivial."]'::jsonb, 1, 'Tiempo de procesamiento y expectativas altas.', 'exam'),
('educacion-inclusiva', 11, 'Un estudiante con TDAH se mueve mucho y no termina las tareas largas. ¿Qué estrategia es más adecuada?', '["Quitarle el recreo hasta que termine las tareas.","Darle más tiempo y pedirle que no se levante hasta terminar.","Sentarlo solo, lejos del grupo, para que no se distraiga.","Dividir la tarea en pasos breves con refuerzo inmediato y permitir pausas activas."]'::jsonb, 3, 'Estructura, instrucciones breves y movimiento.', 'exam'),
('educacion-inclusiva', 12, 'Una docente tiene un estudiante sordo y escribe de espaldas mientras habla. ¿Qué ajuste mejora el acceso?', '["Hablar más fuerte mientras escribe.","Pedirle que copie del compañero.","Hablar mirando al estudiante, escribir y luego explicar, y ubicarlo donde vea el rostro y el pizarrón.","Esperar a que el intérprete resuelva todo lo relacionado con la comunicación, sin modificar su forma de dar la clase."]'::jsonb, 2, 'Apoyos visuales y comunicación clara para estudiantes sordos.', 'exam'),
('educacion-inclusiva', 13, 'Un docente evalúa a un estudiante con dificultades motoras con un examen escrito de 30 minutos, y obtiene una nota baja. ¿Qué cuestiona el enfoque del curso?', '["Que el estudiante no estudió.","Que la nota debe subirse automáticamente, porque con una discapacidad no corresponde evaluar.","Que debe repetir el examen con más tiempo, en el mismo formato.","Que la evaluación mida la escritura y no el aprendizaje; debe ofrecer formatos accesibles."]'::jsonb, 3, 'Evaluación accesible: medir aprendizaje, no discapacidad.', 'exam'),
('educacion-inclusiva', 14, 'Una docente quiere diseñar apoyos para un estudiante con una condición que no conoce bien. ¿Cuál es el mejor paso inicial?', '["Buscar el diagnóstico en internet y aplicarlo tal cual.","Esperar a que el estudiante se adapte y, si no lo logra, pedir un diagnóstico.","Conversar con la familia y los especialistas para conocer fortalezas, necesidades y estrategias que ya funcionan.","Aplicar las mismas estrategias que usó con otro estudiante con esa condición."]'::jsonb, 2, 'Trabajo colaborativo con especialistas y familia.', 'exam'),
('educacion-inclusiva', 15, 'Un docente sigue usando el término ''síndrome de Asperger'' en sus informes. ¿Qué aclara el curso?', '["Que es el término clínico más preciso y actual","Que ya no es un diagnóstico aparte: hoy forma parte del TEA","Que se usa para el autismo en adultos","Que es el término que todavía exigen los informes oficiales escolares"]'::jsonb, 1, 'Con las clasificaciones actuales, el Asperger se integró dentro del TEA. El lenguaje que usamos debe estar actualizado y ser preciso.', 'exam'),
('educacion-inclusiva', 16, '¿Por qué el TEA se llama ''espectro''?', '["Porque se manifiesta de formas y con necesidades de apoyo muy distintas en cada persona","Porque afecta varias áreas del desarrollo en el mismo grado","Porque es una condición temporal que puede desaparecer con la edad","Porque todos los estudiantes con TEA comparten el mismo perfil y necesitan los mismos apoyos"]'::jsonb, 0, 'Dos estudiantes con TEA pueden necesitar apoyos totalmente distintos; por eso se habla de espectro.', 'exam'),
('educacion-inclusiva', 17, 'Un docente dice a un estudiante con TEA: ''¿No te gustaría sentarte ya?''. El estudiante responde ''no'' y sigue de pie. ¿Qué ocurrió?', '["El estudiante desafió al docente a propósito para probar hasta dónde puede llegar frente al grupo","La instrucción fue indirecta; muchos estudiantes con TEA interpretan el lenguaje de forma literal","El estudiante no escuchó la pregunta","Es una señal de que el estudiante necesita una sanción clara para que respete las instrucciones del docente"]'::jsonb, 1, 'Dar instrucciones directas y concretas (''Siéntate, por favor'') evita confusiones por interpretación literal.', 'exam'),
('educacion-inclusiva', 18, 'Un estudiante con TEA tiene un interés profundo por los trenes. ¿Cómo aprovecharlo?', '["Limitarle hablar de trenes en clase para que se concentre en los temas del currículo del grado","Usar los trenes como puerta de entrada: problemas de matemática o lecturas sobre ese tema","No darle importancia porque no está en el currículo","Usarlo como premio al final del día si se porta bien"]'::jsonb, 1, 'Los intereses especiales pueden conectar al estudiante con contenidos del currículo y aumentar su participación.', 'exam'),
('educacion-inclusiva', 19, '¿Cuál es una característica frecuente del lenguaje en estudiantes con síndrome de Down?', '["Expresan mucho más de lo que comprenden","Comprenden más de lo que pueden expresar oralmente","No desarrollan ningún tipo de lenguaje","Su lenguaje es igual al de cualquier estudiante de su edad"]'::jsonb, 1, 'La comprensión suele estar más desarrollada que la expresión oral; subestimar su comprensión es un error común.', 'exam'),
('educacion-inclusiva', 20, '¿Qué dice el curso sobre el TDAH y la crianza?', '["Que el TDAH es causado por falta de disciplina en casa","Que es una condición neurológica real con diferencias medibles, no un problema de crianza","Que mejora si el estudiante se esfuerza más y su familia le pone más límites y rutinas en casa","Que suele desaparecer en la adolescencia"]'::jsonb, 1, 'La evidencia muestra diferencias en el desarrollo y funcionamiento cerebral. Atribuirlo a la crianza o a la voluntad es un mito.', 'exam'),
('educacion-inclusiva', 21, 'Tienes un estudiante ciego en clase y dibujas un triángulo en la pizarra. ¿Qué ajuste aplica?', '["Pedirle que espere a que un compañero le explique después, en el recreo, lo que se dibujó en la pizarra","Describir en voz alta lo que dibujas y, si es posible, ofrecer una figura en relieve para tocar","Darle una hoja con el triángulo impreso en tinta","Explicarle el triángulo más tarde, de forma individual"]'::jsonb, 1, 'Narrar lo visual y ofrecer material táctil permite que acceda al mismo contenido que el grupo.', 'exam'),
('educacion-inclusiva', 22, '¿Qué es la Comunicación Aumentativa y Alternativa (CAA)?', '["Un método para enseñar a hablar a estudiantes sin lenguaje oral","Tableros, pictogramas, señas o tecnología para comunicarse sin depender de la voz","Una terapia para estudiantes sordos","Un tipo de examen adaptado"]'::jsonb, 1, 'La CAA amplía o sustituye el habla; la mayoría de estudiantes sin lenguaje oral sí pueden comunicarse con estos apoyos.', 'exam'),
('educacion-inclusiva', 23, '¿Por qué la evaluación debe ''medir el aprendizaje, no la discapacidad''?', '["Porque los estudiantes con discapacidad no deben ser evaluados","Porque un formato inadecuado puede medir la escritura o la visión en vez de lo que sabe","Porque así se aplica el mismo examen a todo el grupo","Porque la evaluación debe hacerse de forma oral"]'::jsonb, 1, 'Ajustar el formato (oral, más tiempo, material accesible) permite evaluar el mismo objetivo sin que la barrera distorsione el resultado.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('tea-profundidad', 0, '¿Por qué es un error reducir la comunicación de un estudiante con TEA a la etiqueta "verbal" o "no verbal"?', '["Porque los estudiantes con TEA no verbales siempre entienden menos que los verbales, y la etiqueta lo oculta","Porque pierde información clave: hay múltiples niveles de comunicación funcional (fluidez verbal con dificultad social, lenguaje mínimo con CAA, pérdida temporal del habla bajo estrés) que esa etiqueta binaria no captura","Porque la comunicación no verbal no cuenta como comunicación funcional en la escuela","Porque lo que importa es si escribe con fluidez: un estudiante con TEA que escribe bien no necesita apoyos de comunicación aunque tenga dificultades sociales"]'::jsonb, 1, 'La comunicación funcional real de un estudiante con TEA es mucho más matizada que "habla o no habla" — incluye el nivel de comunicación social, el uso de CAA, y hasta la posibilidad de perder el habla temporalmente bajo estrés aunque normalmente sea verbal.', 'lesson'),
('tea-profundidad', 1, '¿Cuál es el objetivo principal de una historia social antes de una situación nueva o difícil para un estudiante con TEA?', '["Advertirle sobre las consecuencias de portarse mal","Describir de forma concreta y en primera persona qué va a pasar y qué puede hacer si se siente abrumado, reduciendo la ansiedad ante lo desconocido","Reemplazar completamente la necesidad de dar instrucciones verbales","Evaluar si el estudiante puede leer bien"]'::jsonb, 1, 'La historia social informa y prepara, en tono neutro y descriptivo, reduciendo la ansiedad que genera lo impredecible — no es una herramienta de advertencia disciplinaria ni de evaluación.', 'lesson'),
('tea-profundidad', 2, '¿Por qué tratar un meltdown como si fuera un berrinche intencional puede empeorar la situación?', '["Porque un meltdown busca un fin, igual que un berrinche, pero de forma más intensa; las consecuencias inmediatas le enseñan que escalar delante del grupo funciona","Porque un meltdown es una sobrecarga sin control voluntario: en ese momento el estudiante no puede autorregularse y las sanciones no ayudan","Porque castigar delante del grupo avergüenza al estudiante, aunque la conducta sea intencional","Porque las consecuencias solo funcionan si se aplican al día siguiente, cuando el estudiante está tranquilo"]'::jsonb, 1, 'El meltdown es una pérdida temporal de autorregulación por sobrecarga, no una conducta dirigida a un objetivo. Responder con disciplina inmediata, como si fuera manipulación, ignora esa realidad neurológica y tiende a intensificar la crisis en vez de resolverla.', 'lesson'),
('tea-profundidad', 3, '¿Por qué las transiciones (cambio de una actividad a otra) suelen ser un momento de mayor riesgo de desregulación para estudiantes con TEA?', '["Porque a la mayoría de los estudiantes les cuesta dejar una actividad que les gusta, y en el TEA ese rechazo es más fuerte","Porque se pierde la previsibilidad de la actividad anterior antes de que la siguiente se vuelva clara, y apoyos como avisos anticipados o temporizadores visuales ayudan a suavizar ese momento crítico","Porque en las transiciones el docente presta menos atención y hay más ruido","Porque el estudiante no entiende las instrucciones de la nueva actividad"]'::jsonb, 1, 'Las transiciones generan una pérdida temporal de previsibilidad — el ancla principal para muchos estudiantes con TEA. Anticipar el cambio con avisos, temporizadores visuales y rutinas de transición reduce significativamente el riesgo de desregulación en ese momento específico.', 'lesson'),
('tea-profundidad', 4, 'Dos estudiantes tienen diagnóstico de TEA. Uno se tapa los oídos en el recreo; el otro busca presión y movimiento constantes. ¿Qué conclusión aplica?', '["El perfil es el mismo en todos los estudiantes con TEA, así que basta una estrategia general bien aplicada para todo el grupo.","El primero necesita apoyos; el segundo solo necesita más límites.","Ambos necesitan lo mismo: un espacio silencioso.","Cada estudiante tiene un perfil sensorial distinto (hiper o hiporreactividad) y los apoyos deben individualizarse."]'::jsonb, 3, 'No existe una única receta para el TEA.', 'exam'),
('tea-profundidad', 5, 'Al recibir a un estudiante nuevo con TEA, una docente quiere conocerlo mejor. ¿Qué es lo más útil?', '["Observarlo durante las primeras semanas antes de hablar con nadie.","Construir con la familia un perfil de comunicación, sensibilidades, intereses y apoyos que funcionan.","Pedir el informe del año anterior y seguirlo tal cual.","Aplicar las estrategias que funcionaron con otros estudiantes con TEA."]'::jsonb, 1, 'El perfil individual se construye con la familia.', 'exam'),
('tea-profundidad', 6, 'Un estudiante se desorienta cuando cambia la actividad. La docente le entrega un horario visual con pictogramas. ¿Qué principio aplica?', '["Refuerzo positivo cada vez que acepta el cambio sin quejarse.","Enseñanza estructurada: reducir la ambigüedad del entorno con apoyos visuales previsibles.","Refuerzo social grupal.","Exposición gradual al cambio sin aviso previo."]'::jsonb, 1, 'Los apoyos visuales anticipan lo que viene.', 'exam'),
('tea-profundidad', 7, 'Un estudiante se angustia con la visita de un invitado a clase. ¿Qué herramienta ayuda a prepararlo?', '["Una historia social breve que explique qué pasará, quién viene y qué se espera.","No avisarle nada, para que se acostumbre a los imprevistos y no desarrolle rigidez ante los cambios.","Decirle esa mañana que habrá un invitado.","Sacarlo del aula durante la visita."]'::jsonb, 0, 'Las historias sociales preparan para lo nuevo.', 'exam'),
('tea-profundidad', 8, 'Un estudiante empieza a gritar, cubrirse las orejas y salir corriendo del aula. ¿Qué es lo más adecuado?', '["Pedirle con calma que explique con palabras qué le pasa y que se tranquilice antes de seguir con la actividad.","Reducir estímulos, usar pocas palabras y garantizar su seguridad, sin exigir razonamiento en ese momento.","Reprenderlo frente al grupo.","Aplicar una consecuencia de inmediato."]'::jsonb, 1, 'Durante un meltdown: seguridad y reducción de estímulos.', 'exam'),
('tea-profundidad', 9, 'Un docente confunde un meltdown con un berrinche y lo castiga. ¿Qué diferencia clave pasó por alto?', '["Que el meltdown solo aparece en casa, con la familia.","El meltdown es una sobrecarga fuera de control, sin intención de manipular; el berrinche suele buscar un fin.","Que el berrinche es más grave y requiere más firmeza.","Que ambos se manejan igual, pero el meltdown dura más."]'::jsonb, 1, 'Meltdown no es berrinche.', 'exam'),
('tea-profundidad', 10, 'Pasada la crisis, el estudiante está agotado. ¿Qué necesita?', '["Una conversación inmediata para entender qué pasó.","Tiempo de recuperación en un espacio tranquilo antes de volver a la actividad o conversar.","Volver de inmediato a la tarea.","Explicar frente a todo el grupo lo ocurrido para que los compañeros comprendan y lo apoyen."]'::jsonb, 1, 'La recuperación es parte del proceso.', 'exam'),
('tea-profundidad', 11, 'Una docente quiere enseñar habilidades sociales a un estudiante con TEA. ¿Qué enfoque es más efectivo?', '["Esperar a que las aprenda observando.","Enseñarlas de forma explícita, con práctica guiada y grupos estructurados con compañeros mentores.","Sentarlo con compañeros sociables para que aprenda de ellos.","Pedir que imite a los compañeros sin una guía explícita, porque observar a otros es la forma natural de aprender."]'::jsonb, 1, 'Habilidades sociales explícitas y estructuradas.', 'exam'),
('tea-profundidad', 12, 'El cambio de clase de Matemáticas a Educación Física genera angustia al estudiante. ¿Qué ajuste ayuda más?', '["Avisar con anticipación, usar una señal visual y un objeto de transición.","Avisarle solo en el momento del cambio, para que no se angustie con anticipación.","Evitar los cambios de actividad en su horario.","Darle otra tarea en el aula para que no vaya a Educación Física."]'::jsonb, 0, 'Las transiciones son el momento de mayor riesgo.', 'exam'),
('tea-profundidad', 13, 'Una docente recibe en casa del estudiante una estrategia distinta a la del aula. ¿Qué es lo más recomendable?', '["Aplicar la del aula, porque es la que el docente conoce.","Pedir que la familia use la del aula sin conversar.","Mantener cada estrategia en su contexto.","Coordinar con la familia y el equipo para que las estrategias sean consistentes entre casa y escuela."]'::jsonb, 3, 'Colaboración continua con la familia.', 'exam'),
('tea-profundidad', 14, 'Un estudiante con pocas palabras bajo estrés recibe indicaciones largas y verbales. ¿Qué sería más efectivo?', '["Explicar con más detalle.","Reducir el lenguaje verbal a frases cortas y apoyarlas con imágenes o gestos.","Repetir la misma indicación varias veces.","Esperar a que se calme sin comunicar nada y retomar luego las indicaciones largas."]'::jsonb, 1, 'Reducir la carga verbal bajo estrés.', 'exam'),
('tea-profundidad', 15, '¿Qué es la hiporreactividad sensorial en el TEA?', '["Sentir un estímulo como mucho más intenso de lo habitual, hasta el punto de evitarlo","Registrar menos un estímulo y por eso buscarlo más (presión, movimiento, sonidos)","Tener sensibilidad normal en todos los sentidos","Reaccionar más a estímulos visuales que auditivos"]'::jsonb, 1, 'La hiperreactividad es sentir de más; la hiporreactividad, sentir de menos y buscar más estímulo. Pueden coexistir en una misma persona según el sentido.', 'exam'),
('tea-profundidad', 16, '¿En qué se basa la enseñanza estructurada (inspirada en TEACCH)?', '["En reducir la ambigüedad del entorno: espacios, tiempos y tareas organizados y predecibles","En exponer al estudiante a cambios frecuentes y sin aviso para que aprenda a tolerarlos mejor con el tiempo","En dar instrucciones verbales más detalladas","En trabajar de forma individual, separado del grupo"]'::jsonb, 0, 'Organizar el espacio, el tiempo y las tareas de forma clara y visual reduce la incertidumbre y favorece la autonomía.', 'exam'),
('tea-profundidad', 17, '¿Para qué sirve una tira visual de tareas?', '["Para registrar qué tareas terminó cada día","Para mostrar los pasos de una tarea en secuencia y que el estudiante avance con más autonomía","Para que el docente controle el tiempo de cada tarea","Para reemplazar la explicación del docente"]'::jsonb, 1, 'Ver cada paso en orden reduce la dependencia de instrucciones orales repetidas.', 'exam'),
('tea-profundidad', 18, '¿Cuál es una señal típica de escalada antes de un meltdown?', '["Que el estudiante pida ir al baño","Taparse los oídos y aumentar los movimientos repetitivos","Que el estudiante hable sin parar de su tema de interés favorito","Que termine la tarea antes que los demás"]'::jsonb, 1, 'Reconocer estas señales tempranas permite reducir estímulos o anticipar una pausa antes de que llegue la crisis.', 'exam'),
('tea-profundidad', 19, 'Durante un meltdown activo, ¿cuál es el objetivo inmediato?', '["Explicarle por qué su conducta es incorrecta","Seguridad y reducción de estímulos: bajar tu voz, menos palabras, espacio tranquilo","Aplicar la consecuencia de inmediato, en ese mismo momento, para que entienda que no puede repetirse","Pedir a todo el grupo que lo observe en silencio"]'::jsonb, 1, 'En plena crisis no hay espacio para enseñar ni corregir; primero se protege y se reduce la sobrecarga.', 'exam'),
('tea-profundidad', 20, '¿Por qué muchos estudiantes con TEA necesitan que las habilidades sociales se enseñen de forma explícita?', '["Porque no les interesa relacionarse","Porque las reglas sociales no escritas no siempre se captan solo observando","Porque así se cumple con el programa de orientación","Porque así se evitan conflictos con los compañeros"]'::jsonb, 1, 'Turnos de conversación o distancia personal pueden enseñarse con ejemplos concretos, práctica y retroalimentación.', 'exam'),
('tea-profundidad', 21, 'El recreo libre es el momento más difícil del día para un estudiante con TEA. ¿Qué estrategia propone el curso?', '["Dejarlo en el aula durante todo el recreo","Ofrecer opciones estructuradas, como un juego con reglas claras o un compañero mentor","Obligarlo a integrarse sin apoyo, para que se acostumbre poco a poco","Pedir a un adulto que lo acompañe durante todo el recreo, en un espacio aparte del grupo"]'::jsonb, 1, 'La interacción estructurada y el apoyo de compañeros mentores facilitan la participación social.', 'exam'),
('tea-profundidad', 22, 'Un estudiante con TEA es muy hábil hablando de su tema favorito pero se pierde en conversaciones grupales. ¿Qué conclusión es correcta?', '["Que no necesita apoyos de comunicación, porque habla muy bien de los temas que conoce","Que su comunicación depende del contexto: puede necesitar apoyos en lo social","Que lo hace a propósito para evitar al grupo","Que debe dejar de hablar de su tema favorito"]'::jsonb, 1, 'La etiqueta ''verbal'' no basta: la fluidez en un tema no garantiza manejar la comunicación social.', 'exam'),
('tea-profundidad', 23, 'Después de una crisis, el estudiante dice sentirse avergonzado. ¿Qué es lo más adecuado?', '["Recordarle frente al grupo lo que pasó para que todos entiendan","Darle tiempo de recuperación y, más tarde y en privado, hablar con calma de lo que lo ayudó","Exigirle que retome la tarea de inmediato","Llamar a su familia para que lo recoja"]'::jsonb, 1, 'La recuperación requiere tiempo y un trato sin exposición. Revisar después qué ayudó prepara mejor la próxima vez.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('discapacidad-down-tdah', 0, '¿Por qué es un error subestimar la comprensión de un estudiante con síndrome de Down basándose solo en su fluidez al hablar?', '["Porque la fluidez depende sobre todo del vocabulario aprendido en casa","Porque es común que la comprensión del lenguaje esté más desarrollada que la expresión oral — la dificultad para expresarse no significa que no comprenda","Porque la comprensión y la expresión van al mismo nivel, así que basta escuchar cómo habla","Porque el lenguaje no es un área relevante en el síndrome de Down"]'::jsonb, 1, 'La brecha entre comprensión (receptiva) y expresión (expresiva) es un patrón común en síndrome de Down. Evaluar la comprensión real mediante formas alternativas de respuesta —no solo la fluidez oral— evita subestimar lo que el estudiante genuinamente entiende.', 'lesson'),
('discapacidad-down-tdah', 1, '¿Por qué dar tiempo extra de procesamiento después de hacer una pregunta beneficia específicamente a un estudiante con síndrome de Down?', '["Porque así se evita que se sienta presionado frente al grupo, aunque el tiempo no cambie su respuesta","Porque procesar y formular la respuesta puede tomarle más tiempo, y completarla por él no le deja mostrar lo que sabe","Porque es una norma de inclusión, sin relación con el procesamiento cognitivo","Porque aplica sobre todo en exámenes escritos; en preguntas orales conviene completarle la respuesta para que no se sienta incómodo"]'::jsonb, 1, 'El tiempo de procesamiento adicional respeta el ritmo cognitivo real del estudiante, permitiéndole formular y expresar una respuesta que refleje genuinamente su comprensión, en vez de una respuesta apurada o completada por otra persona.', 'lesson'),
('discapacidad-down-tdah', 2, '¿Por qué entender el TDAH principalmente como una diferencia en las funciones ejecutivas es más útil que entenderlo solo como "falta de atención"?', '["Porque las funciones ejecutivas explican el TDAH solo en adultos, no en niños ni adolescentes, así que el enfoque cambia según la edad","Porque explica mejor patrones específicos como el hiperfoco en tareas de interés, y por qué estrategias como apoyos externos para memoria de trabajo o enseñanza explícita de autorregulación funcionan mejor que solo pedir \"más atención\"","Porque significa que el estudiante no puede concentrarse en nada, así que conviene reducirle las tareas","Porque es un término más técnico que suena mejor en los informes, aunque en la práctica significa lo mismo que pedirle más atención"]'::jsonb, 1, 'El marco de funciones ejecutivas (memoria de trabajo, control inhibitorio, flexibilidad cognitiva, planificación) explica con más precisión los patrones reales del TDAH — incluido el hiperfoco selectivo— y orienta hacia estrategias de apoyo específicas y efectivas, más allá de simplemente pedir más esfuerzo de atención.', 'lesson'),
('discapacidad-down-tdah', 3, '¿Por qué anticipar pausas activas ANTES de que la inquietud llegue a su punto máximo es más efectivo que solo corregir la disrupción después de que ocurre?', '["Porque las pausas anticipadas cansan menos al docente, aunque en el estudiante el efecto sea el mismo que corregir después","Porque una estrategia proactiva, basada en observar los patrones reales del grupo, previene la disrupción antes de que ocurra, mientras que reaccionar después ya implica gestionar una situación fuera de control con mayor costo de tiempo y clima de aula","Porque las pausas activas funcionan mejor cuando el estudiante las pide, así que conviene esperar a que lo haga","Porque reaccionar después es más rápido, y las pausas programadas quitan tiempo de clase, así que conviene usarlas solo cuando la disrupción ya se volvió inmanejable"]'::jsonb, 1, 'La estrategia proactiva (anticipar según patrones observados) previene la escalación de la inquietud antes de que se convierta en disrupción, resultando en menos tiempo de clase perdido y un clima de aula más positivo que la gestión reactiva después del hecho.', 'lesson'),
('discapacidad-down-tdah', 4, 'Una docente nota que una estudiante con síndrome de Down aprende mejor con imágenes que con instrucciones orales. ¿Cómo aprovecha esa fortaleza?', '["Reemplaza las explicaciones orales por imágenes.","Le da tareas más sencillas que al grupo.","Complementa las explicaciones con apoyos visuales, tarjetas e imágenes y gestos.","Evita el material visual para no distraerla y se concentra en explicaciones orales."]'::jsonb, 2, 'La memoria visual suele ser una fortaleza.', 'exam'),
('discapacidad-down-tdah', 5, 'Un estudiante con síndrome de Down comprende mucho más de lo que puede expresar. ¿Qué debe evitar el docente?', '["Hablarle con claridad y frases cortas.","Darle tiempo para responder, aunque se demore.","Asumir que no comprende porque le cuesta hablar; debe ofrecer apoyos.","Usar gestos y señas."]'::jsonb, 2, 'Comprensión y expresión pueden diferir.', 'exam'),
('discapacidad-down-tdah', 6, 'Una docente enseña un concepto nuevo a un estudiante con síndrome de Down en tres pasos largos. ¿Qué cambio es más útil?', '["Dividir en pasos pequeños, combinar canales sensoriales y practicar repetidamente.","Explicar una sola vez, más rápido y con más ejemplos.","Cambiar el contenido por otro más fácil.","Repetir los mismos tres pasos hasta que los memorice."]'::jsonb, 0, 'Instrucción multisensorial y en pasos pequeños.', 'exam'),
('discapacidad-down-tdah', 7, 'En un examen, a un estudiante con síndrome de Down le cuesta escribir. ¿Qué alternativa evalúa mejor su aprendizaje?', '["Darle más tiempo para escribir, aunque la escritura sea lo que le cuesta.","Dejarle responder de forma oral o con imágenes, evaluando el mismo contenido.","Eximirlo de la evaluación.","Pedir que un compañero escriba lo que él dicte, sin revisar si de verdad comprendió el tema."]'::jsonb, 1, 'Evaluación adaptada: mostrar lo que sabe.', 'exam'),
('discapacidad-down-tdah', 8, 'Un estudiante con TDAH olvida los pasos de una tarea con varias indicaciones. ¿Qué apoyo reduce la carga de memoria de trabajo?', '["Repetir las instrucciones más despacio.","Recordarle las instrucciones cada vez que se equivoque.","Darle solo actividades de una sola instrucción corta.","Una lista visual de pasos con casillas para marcar."]'::jsonb, 3, 'Apoyar la memoria de trabajo con recursos externos.', 'exam'),
('discapacidad-down-tdah', 9, 'Un estudiante con TDAH se frustra y explota ante un error. La docente le grita ''cálmate''. ¿Qué enfoque propone el curso?', '["Exigirle calma de inmediato y con firmeza, para que aprenda a controlarse solo sin ayuda.","Sacarlo del aula hasta que se tranquilice.","Enseñar y practicar estrategias de autorregulación en momentos de calma y anticiparlas.","No reaccionar y seguir con la clase."]'::jsonb, 2, 'Autorregulación: enseñar, no solo exigir.', 'exam'),
('discapacidad-down-tdah', 10, '¿Dónde conviene ubicar a un estudiante con TDAH para reducir la distracción sin aislarlo?', '["Al fondo del aula, para que no distraiga a los demás.","Frente a la puerta, para que pueda salir rápido cuando necesite moverse.","Cerca del docente y lejos de ventanas o zonas de paso, junto a compañeros que sirvan de modelo.","En un escritorio aparte, mirando a la pared."]'::jsonb, 2, 'Ambiente físico que reduce distracción sin aislar.', 'exam'),
('discapacidad-down-tdah', 11, 'Un docente da un ''muy bien'' general al final del día a un estudiante con TDAH. ¿Cómo mejoraría el refuerzo?', '["Esperar al final de la semana y darle un reconocimiento más grande frente a todo el grupo.","Elogiar de inmediato y en concreto: ''Terminaste los tres ejercicios sin levantarte''.","Dar premios materiales por todo lo que haga.","Darle un premio material al final del día si se portó bien."]'::jsonb, 1, 'Refuerzo positivo inmediato y específico.', 'exam'),
('discapacidad-down-tdah', 12, 'Un docente suele esperar a que el estudiante con TDAH se levante para intervenir. ¿Qué cambio es más eficaz?', '["Programar pausas activas breves antes de que la inquietud llegue a su punto máximo.","Reaccionar con firmeza cada vez que se levante, recordándole las reglas del aula frente al grupo.","Quitarle el recreo si se levanta.","Dejar que se mueva cuando quiera, sin estructura."]'::jsonb, 0, 'Anticipar en vez de solo reaccionar.', 'exam'),
('discapacidad-down-tdah', 13, 'Una familia aplica en casa un sistema de refuerzo distinto al de la escuela para su hijo con TDAH. ¿Qué es recomendable?', '["Mantener ambos sistemas independientes.","Pedir a la familia que adopte el sistema de la escuela y deje el de casa.","Retirar el refuerzo en la escuela para no duplicar.","Acordar con la familia estrategias consistentes entre casa y escuela."]'::jsonb, 3, 'Colaborar con la familia.', 'exam'),
('discapacidad-down-tdah', 14, 'La docente siente que debe ''forzar'' que un estudiante con TDAH esté quieto para aprender. ¿Qué enfoque contradice?', '["El de dar instrucciones breves.","El del refuerzo positivo.","El de la colaboración con la familia.","El de dar espacio al movimiento: permitir pausas y moverse puede mejorar la atención."]'::jsonb, 3, 'Movimiento y pausas activas.', 'exam'),
('discapacidad-down-tdah', 15, '¿Qué fortaleza relativa describe la investigación en el perfil cognitivo típico del síndrome de Down?', '["La memoria auditiva de corto plazo","La memoria visual y el aprendizaje social por imitación","El cálculo mental rápido","La lectura de textos extensos sin necesidad de apoyos visuales"]'::jsonb, 1, 'Sin generalizar a cada persona, suele haber fortalezas en memoria visual e imitación, y más dificultad en memoria auditiva de corto plazo.', 'exam'),
('discapacidad-down-tdah', 16, 'Un estudiante con síndrome de Down habla con poca claridad. ¿Qué explica el curso sobre la articulación?', '["Que demuestra que no comprende el vocabulario","Que el tono muscular bajo puede afectar la articulación: es motor, no de comprensión","Que se corrige pidiéndole que repita más rápido","Que conviene no pedirle participar oralmente"]'::jsonb, 1, 'La dificultad articulatoria es motora. Confundirla con falta de comprensión lleva a subestimar al estudiante.', 'exam'),
('discapacidad-down-tdah', 17, '¿Por qué las rutinas predecibles ayudan a estudiantes con síndrome de Down?', '["Porque permiten repetir los mismos contenidos cada día","Porque reducen la carga de adaptarse a la novedad y dejan más capacidad para aprender el contenido","Porque así el estudiante ya no necesita apoyos visuales","Porque los estudiantes con síndrome de Down no toleran ningún cambio"]'::jsonb, 1, 'Una estructura consistente libera recursos cognitivos para lo que realmente importa: el aprendizaje.', 'exam'),
('discapacidad-down-tdah', 18, '¿Qué son las funciones ejecutivas?', '["La capacidad de memorizar datos y fórmulas","Habilidades como memoria de trabajo, control de impulsos, planificación y flexibilidad","Las habilidades para liderar y organizar a otros","Un tipo de inteligencia que tienen algunos estudiantes"]'::jsonb, 1, 'El TDAH afecta principalmente estas habilidades; entenderlo así orienta apoyos concretos.', 'exam'),
('discapacidad-down-tdah', 19, '¿Qué propone el curso sobre la autorregulación en estudiantes con TDAH?', '["Que es una cuestión de voluntad: basta con exigirle ''cálmate'' con firmeza cada vez","Que es una habilidad que se enseña y se practica con estrategias concretas","Que los estudiantes con TDAH no pueden desarrollarla","Que se logra sobre todo con medicación"]'::jsonb, 1, 'La autorregulación se aprende: con modelado, práctica y apoyos, no solo con exigencias.', 'exam'),
('discapacidad-down-tdah', 20, '¿Qué apoyo de organización externa ayuda a un estudiante con TDAH con tareas de varios pasos?', '["Repetirle la instrucción completa en voz más alta, varias veces, hasta que la memorice","Listas de verificación, agendas visuales y carpetas codificadas por color","Darle tareas más cortas que al resto del grupo","Dejar que se organice solo para que gane autonomía"]'::jsonb, 1, 'El andamiaje externo compensa las dificultades de planificación mientras se desarrollan esas habilidades.', 'exam'),
('discapacidad-down-tdah', 21, '¿Qué tipo de refuerzo funciona mejor con estudiantes con TDAH?', '["Una recompensa grande al final del mes","Retroalimentación inmediata, específica y frecuente sobre la conducta correcta","Un comentario general en la boleta","Ningún refuerzo, para que se acostumbren a trabajar solos como el resto del grupo"]'::jsonb, 1, 'La inmediatez y la especificidad sostienen mejor la motivación que las recompensas lejanas.', 'exam'),
('discapacidad-down-tdah', 22, 'Una docente da la misma instrucción a un estudiante con síndrome de Down: le muestra una imagen, se la dice y le da el objeto para manipular. ¿Qué principio aplica?', '["Instrucción multisensorial en pasos pequeños","Refuerzo positivo diferido","Aprendizaje por descubrimiento, sin guía del docente","Modificación del objetivo"]'::jsonb, 0, 'Combinar ver, escuchar y manipular en pasos pequeños facilita consolidar conceptos, sobre todo abstractos.', 'exam'),
('discapacidad-down-tdah', 23, '¿Por qué conviene que el plan de manejo conductual de un estudiante con TDAH sea consistente entre casa y escuela?', '["Para que la familia aplique en casa las mismas sanciones que se aplican en la escuela","Porque las mismas expectativas y refuerzos en ambos lugares aclaran qué se espera","Para que la escuela aplique el plan que diseñó la familia","Para que el estudiante reciba premios en ambos lugares"]'::jsonb, 1, 'La consistencia reduce la confusión y refuerza las mismas habilidades en ambos contextos.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('lengua-senas-docentes', 0, '¿Por qué es incorrecto pensar que la lengua de señas es simplemente "el español deletreado con las manos"?', '["Porque la lengua de señas es mímica y no tiene reglas fijas","Porque la lengua de señas es un idioma natural completo con su propia gramática y sintaxis, distinta del español — no una traducción letra por letra","Porque usa el alfabeto dactilológico como base de todas las palabras","Porque es exactamente igual en todos los países hispanohablantes"]'::jsonb, 1, 'La lengua de señas tiene estructura gramatical propia, distinta a la del idioma oral del mismo país, y varía además entre países (cada país tiene su propia lengua de señas) — no es un simple código de traducción letra por letra del español.', 'lesson'),
('lengua-senas-docentes', 1, '¿Para qué se usa principalmente el alfabeto dactilológico (deletreo manual) en la lengua de señas?', '["Para toda conversación cotidiana, letra por letra","Para deletrear nombres propios, lugares o palabras técnicas que aún no tienen una seña establecida — no como forma habitual de conversar, ya que sería muy lento","Para conversaciones formales o académicas, donde se necesita precisión","Para enseñar a leer a niños sordos, sin uso en la conversación"]'::jsonb, 1, 'El deletreo manual es una herramienta específica para nombres propios y palabras sin seña conocida — la comunicación fluida cotidiana usa señas establecidas siempre que existen, no deletreo letra por letra, que resultaría muy lento para conversar.', 'lesson'),
('lengua-senas-docentes', 2, '¿Por qué la expresión facial es importante en la lengua de señas, más allá de comunicar emociones?', '["Porque transmite emociones, que es su función principal en la lengua de señas","Porque cumple una función gramatical real — por ejemplo, cejas levantadas para preguntas de sí/no, cejas fruncidas para preguntas con palabra interrogativa — y sin ella la seña puede perder su significado gramatical completo","Porque se usa en contextos informales para dar énfasis","Porque es igual en todas las lenguas de señas del mundo"]'::jsonb, 1, 'A diferencia de los idiomas orales, en las lenguas de señas la expresión facial forma parte de la gramática misma —marca tipos de pregunta, negación, intensidad— no es solo un complemento emocional opcional a la seña manual.', 'lesson'),
('lengua-senas-docentes', 3, 'Cuando trabajas con un intérprete de lengua de señas en el aula, ¿a quién debes dirigirte al hablar con el estudiante sordo?', '["Al intérprete, pidiéndole que le transmita el mensaje al estudiante","Directamente al estudiante sordo, ya que el intérprete es un canal neutral de comunicación, no un participante de la conversación","Es indiferente a quién te dirijas mientras el mensaje llegue","Al intérprete cuando el mensaje es complejo, y al estudiante en lo cotidiano"]'::jsonb, 1, 'El protocolo correcto de trabajo con intérpretes es dirigirse siempre directamente a la persona con quien te estás comunicando —el estudiante sordo—, manteniendo contacto visual y hablándole a él o ella, mientras el intérprete cumple su función neutral de traducción, sin convertirse en el destinatario de la conversación.', 'lesson'),
('lengua-senas-docentes', 4, 'Un docente cree que la lengua de señas es mímica universal. ¿Qué aclaración corresponde?', '["Tiene razón: es un conjunto de gestos naturales y por eso es igual en todo el mundo.","Es un código basado en el idioma oral.","Es un complemento de la lectura labial.","Es un idioma completo con gramática propia y distinta en cada país o comunidad."]'::jsonb, 3, 'La lengua de señas es un idioma completo, no un código.', 'exam'),
('lengua-senas-docentes', 5, 'Una docente piensa que la sordera es una enfermedad que debe ''arreglarse''. ¿Qué modelo refleja y cuál propone el curso?', '["El modelo social; el curso propone el modelo médico, que describe la sordera como una pérdida que hay que corregir.","El modelo de déficit; el curso propone el modelo rehabilitador.","El modelo social; el curso propone el modelo inclusivo.","El modelo médico; el curso propone el modelo social, que enfatiza barreras del entorno y la identidad cultural."]'::jsonb, 3, 'Modelo médico vs. modelo social.', 'exam'),
('lengua-senas-docentes', 6, 'Un docente grita para que un estudiante sordo lo entienda. ¿Qué corrección corresponde?', '["Hablar más fuerte y más cerca.","Esperar a que el estudiante lea los labios sin ningún apoyo adicional, hablando despacio y con voz alta.","Hablar más despacio, exagerando el movimiento de los labios.","Mirar de frente, hablar con claridad, apoyar con escritura y señas básicas, y confirmar la comprensión."]'::jsonb, 3, 'Comunicación visual y clara.', 'exam'),
('lengua-senas-docentes', 7, 'Una docente quiere comunicar el nombre de un estudiante, pero no conoce su seña. ¿Qué es lo adecuado?', '["Deletrear el nombre con el alfabeto dactilológico y luego preguntar cuál es su seña.","Inventar una seña para el estudiante y pedirle que la use.","Evitar usar su nombre.","Pedir a un compañero que se lo señale."]'::jsonb, 0, 'Deletreo cuando no existe seña establecida.', 'exam'),
('lengua-senas-docentes', 8, 'Al dar una instrucción en lengua de señas, una docente mantiene el rostro inexpresivo. ¿Qué ocurre?', '["No pasa nada: lo que cuenta son las manos, y mantener el rostro neutro evita distraer al estudiante.","Se evita confundir al estudiante con gestos de más.","Solo afecta a los saludos y a las emociones.","Se pierde información gramatical: la expresión facial forma parte del significado."]'::jsonb, 3, 'La gramática facial es parte de la lengua.', 'exam'),
('lengua-senas-docentes', 9, 'En clase, hay un intérprete de lengua de señas. ¿Cómo debe actuar el docente?', '["Hablar al intérprete y no al estudiante.","Pedir al intérprete que explique el tema por él mientras avanza la clase, para ahorrar tiempo con el grupo.","Pedir al intérprete un resumen al final de la clase.","Hablar al estudiante y no al intérprete, dar pausas y compartir el material con anticipación."]'::jsonb, 3, 'El papel del intérprete.', 'exam'),
('lengua-senas-docentes', 10, 'Un video del curso no tiene subtítulos. ¿Qué es lo más inclusivo?', '["Activar subtítulos o proporcionar una transcripción antes de proyectarlo.","Proyectarlo y resumir al final.","Reemplazarlo por una explicación oral.","Pedir al estudiante sordo que lo vea en casa con su familia y que luego lo resuma por escrito."]'::jsonb, 0, 'Subtítulos y apoyos visuales en todo material.', 'exam'),
('lengua-senas-docentes', 11, 'Una docente quiere ubicar a un estudiante sordo en el aula. ¿Qué criterio es el más adecuado?', '["En el fondo, para que no distraiga.","Un lugar con buena visibilidad del docente, del pizarrón y de los compañeros, con la luz sobre el rostro de quien habla.","Junto a la ventana a contraluz.","Donde haya menos ruido, sin importar la visibilidad."]'::jsonb, 1, 'Organización visual del aula.', 'exam'),
('lengua-senas-docentes', 12, 'Una docente dice que las personas sordas ''no pueden aprender como los demás''. ¿Qué corresponde?', '["Es un mito: pueden aprender con acceso a una lengua y a apoyos visuales adecuados.","Es cierto en parte: aprenden, pero a un ritmo siempre más lento.","Es cierto si no usan audífonos; con audífonos aprenden igual que cualquier otro estudiante.","Es cierto sobre todo en lectura y escritura."]'::jsonb, 0, 'Mitos sobre la sordera.', 'exam'),
('lengua-senas-docentes', 13, 'Un docente quiere saludar a una estudiante sorda a diario. ¿Qué acción construye relación más allá del idioma?', '["Saludarla por escrito con una nota en su cuaderno.","Aprender saludos y cortesía en lengua de señas y usarlos con respeto, aceptando sus correcciones.","Pedir a otro estudiante que la salude por él para evitar errores.","Saludarla con una sonrisa y un gesto, sin intentar señas."]'::jsonb, 1, 'Construir una relación más allá del idioma.', 'exam'),
('lengua-senas-docentes', 14, 'Una docente planifica instrucciones de aula para un estudiante sordo: sentarse, esperar, empezar. ¿Qué es lo más útil?', '["Inventar gestos propios que el estudiante pueda aprender.","Escribirlas en el pizarrón, sin señas, para que el estudiante las lea cada vez que haga falta en la clase.","Esperar a que el intérprete las enseñe.","Aprender las señas básicas de manejo de aula y acompañarlas de apoyos visuales."]'::jsonb, 3, 'Instrucciones de aula esenciales.', 'exam'),
('lengua-senas-docentes', 15, '¿Qué mito sobre la lectura labial aclara el curso?', '["Que las personas sordas no pueden leer los labios en absoluto, ni siquiera con práctica","Que la leen casi a la perfección: incluso expertos captan solo una parte","Que la lectura labial es igual en todos los idiomas","Que la lectura labial reemplaza la necesidad de intérprete"]'::jsonb, 1, 'La lectura labial capta una parte limitada del mensaje. No reemplaza la lengua de señas ni los apoyos visuales.', 'exam'),
('lengua-senas-docentes', 16, '¿Qué propone el modelo social y cultural de la sordera?', '["Ver la sordera sobre todo como algo que se corrige con audífonos, implantes o terapia del habla","Ver a las personas sordas como una comunidad con lengua y cultura propias, sin barreras","Que las personas sordas deben aprender a hablar antes que a señar","Que la sordera es un asunto de cada familia"]'::jsonb, 1, 'El modelo social pone el foco en las barreras del entorno y reconoce la identidad y la lengua de la Comunidad Sorda.', 'exam'),
('lengua-senas-docentes', 17, '¿Por qué se prefiere una seña establecida antes que deletrear una palabra con el alfabeto dactilológico?', '["Porque el deletreo es menos preciso que la seña","Porque el deletreo es mucho más lento y se reserva para nombres propios o palabras sin seña","Porque el deletreo se usa solo en contextos formales","Porque las señas establecidas son iguales en todos los países"]'::jsonb, 1, 'El deletreo es útil para nombres o términos sin seña, pero es más lento que una seña establecida.', 'exam'),
('lengua-senas-docentes', 18, '¿Es la lengua de señas igual en todos los países?', '["Sí, es un sistema universal que se usa de la misma forma en todos los países","No: cada país o región tiene su propia lengua de señas, con su vocabulario","Sí, salvo pequeñas diferencias de ''acento'' en algunas señas","Es igual en los países que comparten el mismo idioma oral"]'::jsonb, 1, 'Las lenguas de señas son idiomas naturales y varían según la comunidad, como las lenguas orales.', 'exam'),
('lengua-senas-docentes', 19, '¿Qué seña de aula equivale, en lo visual, a pedir ''escuchen''?', '["Esperar (con la mano abierta hacia abajo)","Mirar (en el sentido de ''atención'')","Terminado","Otra vez"]'::jsonb, 1, 'Para un estudiante sordo, pedir atención es pedir que mire; es una de las señas de manejo de aula más útiles.', 'exam'),
('lengua-senas-docentes', 20, '¿Para qué sirve conocer las señas de emociones básicas (feliz, triste, enojado, confundido, cansado)?', '["Para evaluar la conducta del estudiante sordo cada semana","Para hacer un chequeo emocional simple con un estudiante sordo, igual que con el resto del grupo","Para reemplazar al intérprete","Para la clase de arte y las actividades de expresión"]'::jsonb, 1, 'Permite incluir al estudiante sordo en las rutinas de conversación emocional del aula.', 'exam'),
('lengua-senas-docentes', 21, '¿Qué cuidado de iluminación recomienda el curso para un aula con estudiantes sordos?', '["Hablar de espaldas a una ventana muy iluminada","Que la luz ilumine el rostro de quien habla y no quede a contraluz","Mantener el aula a media luz para que el estudiante no se distraiga con estímulos visuales","Ubicar al estudiante de frente a la ventana"]'::jsonb, 1, 'A contraluz, el rostro se oscurece y se pierde información de labios y expresión facial.', 'exam'),
('lengua-senas-docentes', 22, '¿Por qué conviene activar los subtítulos en los videos aunque no haya un estudiante sordo presente?', '["Porque es obligatorio en los centros educativos","Porque también ayudan a quienes aprenden el idioma o tienen dificultades de atención o lectura","Porque permiten bajar el volumen del video","Porque los estudiantes prefieren leer a escuchar"]'::jsonb, 1, 'Los subtítulos son un apoyo de accesibilidad que beneficia a muchos estudiantes, no solo a los sordos.', 'exam'),
('lengua-senas-docentes', 23, 'Una docente aprende solo un vocabulario básico de señas. ¿Qué valor tiene, según el curso?', '["Poco: si no domina la lengua, el intérprete es quien realmente se comunica con el estudiante","Comunica esfuerzo y respeto y fortalece la relación, aunque no reemplaza al intérprete","Permite prescindir del intérprete en las clases sencillas","Sirve para saludar en la entrada y despedirse"]'::jsonb, 1, 'Un vocabulario básico construye vínculo y facilita rutinas, sin sustituir a un intérprete profesional cuando se necesita.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('fundamentos-pisa', 0, 'Según PISA 2025, ¿qué porcentaje de estudiantes de 15 años en Guatemala alcanza el nivel básico (Nivel 2) en matemática?', '["Alrededor del 65%, similar al promedio de los países de la OCDE","Apenas el 8%, muy por debajo del promedio de la OCDE (65%)","Cerca del 50%","Alrededor del 25%"]'::jsonb, 1, 'Solo el 8% de los estudiantes guatemaltecos alcanza el nivel básico en matemática, frente a 65% en el promedio OCDE — la brecha más grande de las tres materias evaluadas, y el punto de partida honesto de este curso.', 'lesson'),
('fundamentos-pisa', 1, '¿Cuál de estas preguntas sobre un texto es de tipo INFERENCIAL, no literal?', '["¿En qué año ocurrió el evento que describe el texto?","¿Por qué crees que el personaje tomó esa decisión, aunque el texto no lo explique directamente?","¿Cómo se llama el lugar donde ocurre la historia?","¿Cuántos personajes aparecen y cómo se llama cada uno de ellos en el texto?"]'::jsonb, 1, 'Las preguntas inferenciales piden ir más allá de lo escrito literalmente, conectando pistas del texto para construir un significado que no está dicho de forma explícita — son las que menos se practican y las que PISA mide con más peso.', 'lesson'),
('fundamentos-pisa', 2, 'Un estudiante sabe multiplicar correctamente pero no logra decidir qué operación usar frente a un problema de la vida real. ¿Qué habilidad específica le falta, según este módulo?', '["Necesita practicar más la multiplicación","Traducir la situación real a un problema matemático — el piso básico que PISA mide","Necesita reforzar el cálculo mental","Necesita memorizar más tablas y practicar operaciones más rápido"]'::jsonb, 1, 'El piso básico (Nivel 2) en matemática es justamente esa traducción de una situación real a una representación matemática — dominar la operación en sí no es suficiente si falta ese paso previo de interpretación.', 'lesson'),
('fundamentos-pisa', 3, 'Según PISA 2025, ¿qué porcentaje de estudiantes en Guatemala faltó al menos un día de clases en las dos semanas antes de la prueba, y cómo se compara con el promedio OCDE?', '["22%, igual al promedio OCDE","43%, el doble que la OCDE (22%)","10%, muy por debajo del promedio OCDE","30%, algo por encima del promedio OCDE"]'::jsonb, 1, 'El 43% de inasistencia en Guatemala más que duplica el promedio OCDE (22%), y casi se duplicó frente al propio dato de Guatemala en 2022 (19%) — es una de las brechas más grandes y de más rápido crecimiento del informe.', 'lesson'),
('fundamentos-pisa', 4, 'De todo lo trabajado en este curso, ¿cuál es la idea central que conecta el diagnóstico de PISA con las estrategias de los módulos siguientes?', '["Los estudiantes no tienen capacidad para el nivel avanzado","La mayoría no llega al piso funcional en lectura, matemática y ciencia — pero eso se construye con estrategias concretas, sostenidas y accesibles con los recursos que ya existen","El problema es sobre todo de falta de recursos: con más libros, computadoras y laboratorios los resultados mejorarían por sí solos","Los resultados dependen del contexto familiar, y el docente individual puede hacer poco frente a ellos"]'::jsonb, 1, 'El diagnóstico de PISA no es un techo de capacidad, es un punto de partida: con estrategias concretas de comprensión lectora, razonamiento matemático aplicado, mentalidad de crecimiento y asistencia sostenida — aplicables con los recursos que ya existen en el aula — es posible construir el piso funcional que hoy le falta a la mayoría.', 'lesson'),
('fundamentos-pisa', 5, 'Una docente tiene estudiantes que no distinguen la idea principal de un texto. ¿Qué estrategia del curso es más adecuada?', '["Pedir que subrayen todo lo que les parezca importante.","Dividir el texto en fragmentos cortos y pedir la idea principal tras cada fragmento.","Hacerles leer más rápido para que practiquen con más textos.","Evaluar con preguntas de recuerdo de detalles."]'::jsonb, 1, 'La idea principal, tarjeta por tarjeta.', 'exam'),
('fundamentos-pisa', 6, 'Un docente pregunta ''¿cómo se llama el personaje principal?''. ¿Qué tipo de pregunta mide mejor la comprensión?', '["Una pregunta inferencial: ''¿por qué crees que el personaje tomó esa decisión?''","Otra de recuerdo literal.","Preguntas de opción múltiple sin justificar, porque permiten corregir rápido a todo el grupo.","Una pregunta sobre el escenario: ''¿dónde ocurre la historia?''"]'::jsonb, 0, 'Preguntas que sí miden comprensión.', 'exam'),
('fundamentos-pisa', 7, 'Antes de una lectura con palabras nuevas, ¿cuál es la mejor preparación?', '["Pedir que busquen todas las palabras desconocidas en el diccionario antes de empezar a leer el texto.","Leer sin explicar.","Enseñar 3 a 5 palabras clave con un ejemplo cercano y activar lo que ya saben del tema.","Entregar un glosario extenso sin práctica."]'::jsonb, 2, 'Vocabulario y conocimientos previos.', 'exam'),
('fundamentos-pisa', 8, 'En un problema de compras, una estudiante sabe sumar y multiplicar, pero no sabe cuál usar. ¿Qué dificultad tiene?', '["Traducir la situación a una operación; hay que trabajar la modelización.","Cálculo lento; hay que practicar más operaciones.","Comprensión lectora; hay que leerle el problema en voz alta.","Falta de atención; conviene repetir el problema varias veces hasta que lo memorice."]'::jsonb, 0, 'El problema no es la operación, es traducir la situación.', 'exam'),
('fundamentos-pisa', 9, 'Antes de resolver un problema de matemática, un docente pide: ''¿dará más o menos de 100?''. ¿Qué estrategia usa?', '["Estimar antes de calcular, para dar sentido al resultado y detectar errores.","Calcular mentalmente sin papel.","Redondear los números para simplificar el cálculo.","Comprobar con calculadora."]'::jsonb, 0, 'Estimar antes de calcular.', 'exam'),
('fundamentos-pisa', 10, 'Una estudiante dice: ''soy mala para matemática''. ¿Qué respuesta fomenta mentalidad de crecimiento?', '["''Todavía no lo dominas; mira cuánto mejoraste en este tipo de problemas''.","''No te preocupes, no todos sirven para matemática, cada quien tiene un talento distinto.''","''Eres muy inteligente, lo harás bien.''","''No pasa nada, a mí también me costaba.''"]'::jsonb, 0, 'Cómo hablar del error y del esfuerzo.', 'exam'),
('fundamentos-pisa', 11, 'Una estudiante falta con frecuencia y su rendimiento cae. ¿Qué respuesta del docente es más útil?', '["Reprobarla por faltas.","Conversar con ella y su familia para entender las causas y acordar apoyos y seguimiento.","Bajarle la nota de participación para que no falte.","Enviarle más tareas para que se ponga al día, sin conversar con ella ni con su familia sobre las faltas."]'::jsonb, 1, 'Las primeras señales de una ausencia que se vuelve costumbre.', 'exam'),
('fundamentos-pisa', 12, 'Un docente de una escuela con pocos materiales quiere trabajar matemática. ¿Qué enfoque es realista?', '["Usar materiales del entorno (semillas, tapas, cuerdas) para representar.","Usar solo el libro de texto y ejercicios en el cuaderno.","Pedir donaciones de material didáctico antes de empezar.","Pedir que cada estudiante compre su propio material."]'::jsonb, 0, 'Matemática con lo que hay.', 'exam'),
('fundamentos-pisa', 13, 'Un docente quiere hacer visibles las estrategias de los estudiantes. ¿Qué recurso propone el curso?', '["Una tabla con la respuesta correcta de cada ejercicio.","Un ranking de resultados visible para todo el grupo.","Una pizarra compartida donde los estudiantes anotan las estrategias que usaron.","Un cuaderno del docente donde anota en privado las estrategias de cada estudiante."]'::jsonb, 2, 'Hacerlo visible.', 'exam'),
('fundamentos-pisa', 14, 'Un docente de un grupo con rendimiento bajo quiere preparar a sus estudiantes solo con simulacros de la prueba. ¿Qué advertencia del curso aplica?', '["Trabajar habilidades transferibles, no solo enseñar para la prueba.","Los simulacros son la única forma de mejorar los resultados, por lo que deben ocupar todo el año.","Que los simulacros solo sirven el último mes antes de la prueba.","Que conviene suspender todo simulacro y no hablar de la prueba."]'::jsonb, 0, 'El curso apoya la materia, no la reemplaza ni enseña para la prueba.', 'exam'),
('fundamentos-pisa', 15, '¿Qué significa alcanzar el ''nivel básico'' (Nivel 2) en matemática según PISA?', '["Resolver problemas avanzados de álgebra y cálculo","Interpretar una situación cotidiana simple y representarla matemáticamente","Memorizar las tablas de multiplicar","Aprobar el examen nacional de matemática"]'::jsonb, 1, 'El Nivel 2 no es avanzado: es el piso funcional para usar la matemática en situaciones cotidianas simples.', 'exam'),
('fundamentos-pisa', 16, 'Antes de entregar un texto sobre volcanes, una docente pregunta durante 2 minutos qué saben ya del tema. ¿Qué estrategia aplica?', '["Activar conocimientos previos","Evaluación sumativa","Lectura veloz con cronómetro y metas","Lectura guiada"]'::jsonb, 0, 'Conectar el texto con algo que ya se sabe facilita comprenderlo, aunque lo previo sea poco o desordenado.', 'exam'),
('fundamentos-pisa', 17, 'Mientras lee un párrafo, el docente dice en voz alta: ''Acá me imagino que…'', ''Esto me hace pensar que…''. ¿Para qué sirve?', '["Para mostrar la entonación correcta","Para modelar cómo piensa un lector que comprende","Para que los estudiantes copien sus comentarios","Para evaluar la pronunciación y la fluidez de cada estudiante del grupo"]'::jsonb, 1, 'Pensar en voz alta hace visible el proceso de comprensión que los estudiantes pueden imitar.', 'exam'),
('fundamentos-pisa', 18, '¿Qué rutina de lectura construye más comprensión, según el curso?', '["Un texto largo, una sola vez al mes","Un texto corto leído varias veces por semana","Lectura libre durante el recreo","Leer un libro completo por periodo"]'::jsonb, 1, 'La frecuencia entrena el hábito y la resistencia lectora mejor que una lectura larga y esporádica.', 'exam'),
('fundamentos-pisa', 19, 'Un estudiante solo puede ''resumir'' repitiendo frases exactas del texto. ¿Qué indica?', '["Que comprendió muy bien el texto","Que probablemente aún no ha comprendido: resumir con sus propias palabras es la prueba","Que tiene buena memoria y ya domina la comprensión","Que el texto era demasiado corto"]'::jsonb, 1, 'Reformular sin copiar muestra comprensión; repetir textual puede ser solo memoria.', 'exam'),
('fundamentos-pisa', 20, '¿Qué textos propone el curso para ''leer para hacer''?', '["Novelas y cuentos clásicos","Instrucciones de un juego, una receta, un horario de buses o un instructivo","Definiciones de diccionario","Resúmenes del libro de texto para memorizar"]'::jsonb, 1, 'Son textos que exigen usar la información, justo el tipo de lectura funcional que mide PISA.', 'exam'),
('fundamentos-pisa', 21, '¿Qué propone el curso sobre el orden de enseñanza en matemática?', '["Primero el algoritmo, bien practicado, y después un problema inventado para aplicarlo","Primero una situación real y concreta, y desde ella llegar al procedimiento","Trabajar algoritmos y contexto por separado, en días distintos","Evitar los problemas de la vida real hasta dominar las operaciones"]'::jsonb, 1, 'Empezar por el contexto ayuda a decidir qué operación usar, que es justamente la dificultad central.', 'exam'),
('fundamentos-pisa', 22, 'Una docente pide resolver el mismo problema de dos formas distintas y comparar. ¿Qué desarrolla?', '["La dependencia de un único método correcto","Flexibilidad de pensamiento y comprensión, valorando varias estrategias válidas","Velocidad de cálculo sin comprensión","La memorización del procedimiento del libro, para que todos lo resuelvan exactamente igual"]'::jsonb, 1, 'Comparar caminos ayuda a entender por qué funciona cada uno.', 'exam'),
('fundamentos-pisa', 23, '¿Qué recomienda el curso para la práctica matemática?', '["Una hora seguida, una sola vez por semana","Poco pero seguido: unos 10 minutos varias veces por semana","Practicar mucho la semana antes del examen","No practicar tanto: basta con entender bien la explicación del docente"]'::jsonb, 1, 'La práctica espaciada retiene mejor que una sesión larga concentrada.', 'exam')
INSERT INTO public.exam_questions (course_id, idx, text, options, correct, explanation, source) VALUES
('master:steam20', 0, '¿Qué diferencia fundamentalmente a STEAM de una enseñanza disciplinar separada?', '["Que STEAM usa más tecnología digital en cada una de las clases","Que integra disciplinas para resolver problemas reales","Que STEAM agrega arte a las clases de ciencias","Que STEAM trabaja por proyectos y no por temas"]'::jsonb, 1, 'La integración es la clave: los estudiantes no aprenden Ciencia, Tecnología, Ingeniería, Emprendimiento, Artes y Matemáticas por separado, sino aplicadas juntas ante problemas auténticos.', 'exam'),
('master:steam20', 1, 'Un docente STEAM eficaz diseña situaciones de aprendizaje donde:', '["Se usa tecnología digital en cada actividad","Integra al menos tres disciplinas de forma auténtica","Cada disciplina se trabaja por separado y luego se juntan los resultados","El docente explica la teoría y luego los alumnos hacen un experimento"]'::jsonb, 1, 'La autenticidad y la integración real son el sello distintivo de STEAM. Sin ambas, es STEM disfrazado.', 'exam'),
('master:steam20', 2, '¿Cuál es el rol de las Artes en STEAM según Yakman?', '["Mejorar la presentación final de los proyectos científicos","Aportar creatividad, diseño y pensamiento estético que amplía las soluciones posibles","Reemplazar la tecnología en aulas sin recursos","Dar un espacio de expresión libre al final del proyecto"]'::jsonb, 1, 'Las Artes no adornan STEAM: son el componente que libera la creatividad necesaria para innovar. Sin ellas, las soluciones técnicas carecen de humanidad y estética.', 'exam'),
('master:steam20', 3, 'En ABP, ¿qué hace que una Pregunta Guía sea realmente efectiva?', '["Que tenga una respuesta correcta única","Que provenga del libro de texto oficial","Que sea abierta y conectada con la vida real","Que pueda resolverse en una sola clase con la información del libro"]'::jsonb, 2, 'Una buena Pregunta Guía genera curiosidad sostenida porque no tiene respuesta simple ni única. Conecta el contenido escolar con problemas reales.', 'exam'),
('master:steam20', 4, '¿Por qué la reflexión final ("debriefing") es crítica en un proyecto ABP?', '["Permite poner nota al producto","Consolida el aprendizaje, identifica qué funcionó y qué cambiar en el próximo ciclo","Reemplaza la evaluación sumativa","Es opcional si el tiempo es limitado, ya que el aprendizaje ocurrió durante el proyecto"]'::jsonb, 1, 'Sin reflexión, el ABP se convierte en "hacer cosas". El debriefing convierte la experiencia en aprendizaje transferible.', 'exam'),
('master:steam20', 5, 'La evaluación en ABP debe centrarse principalmente en:', '["El producto final, porque es lo único que se puede evaluar con objetividad","El proceso, las competencias y el producto como evidencia","La nota del examen al final del proyecto","La puntualidad en la entrega de cada avance"]'::jsonb, 1, 'En ABP el proceso es tan importante como el producto. Las rúbricas deben capturar competencias como colaboración, investigación y pensamiento crítico, no solo el resultado.', 'exam'),
('master:steam20', 6, '¿Por qué el Design Thinking comienza siempre con la fase de empatía?', '["Porque así lo establece el método original de Stanford","Porque sin entender a las personas que viven el problema, cualquier solución es una suposición","Porque así se motiva al equipo antes de idear","Porque es la fase más sencilla y permite avanzar rápido"]'::jsonb, 1, 'La empatía garantiza que resuelves el problema real, no el que asumes que existe. Sin ella, brillantes soluciones pueden ser completamente irrelevantes.', 'exam'),
('master:steam20', 7, 'En Design Thinking, el prototipo rápido tiene como objetivo principal:', '["Crear el producto final para presentar","Aprender rápido y barato antes de invertir más","Validar que la idea elegida es la correcta","Sustituir la investigación de campo con una versión final lista para usar"]'::jsonb, 1, '"Falla rápido, aprende rápido" es el principio del prototipado. Un prototipo en 30 minutos que revela problemas vale más que semanas de planificación.', 'exam'),
('master:steam20', 8, '¿Qué distingue la evaluación formativa de la sumativa?', '["La formativa no lleva nota y la sumativa sí","La formativa ocurre durante el proceso para mejorarlo","La formativa se aplica al inicio y la sumativa al final","La sumativa es más importante para el docente"]'::jsonb, 1, 'La evaluación formativa es un proceso continuo de retroalimentación que ajusta la enseñanza en tiempo real. La sumativa certifica qué se logró. Ambas son necesarias y complementarias.', 'exam'),
('master:steam20', 9, 'Una rúbrica analítica eficaz:', '["Describe con detalle el nivel máximo de desempeño","Describe niveles de desempeño para cada criterio","Asigna un puntaje total al trabajo completo","Reemplaza la observación del docente"]'::jsonb, 1, 'La rúbrica analítica desglosa el desempeño por criterios. Al compartirla antes de la actividad, se convierte en guía de aprendizaje, no solo en herramienta de calificación.', 'exam'),
('master:steam20', 10, 'La autoevaluación y coevaluación son valiosas porque:', '["Reducen el trabajo del docente","Desarrollan metacognición y autorregulación","Permiten que la nota sea más justa","Funcionan mejor con estudiantes mayores y responsables"]'::jsonb, 1, 'Cuando los estudiantes evalúan su propio trabajo y el de sus pares con criterios claros, desarrollan la capacidad de monitorear y ajustar su propio aprendizaje — habilidad clave del siglo XXI.', 'exam'),
('master:steam20', 11, 'El Efecto Pigmalión en educación demuestra que:', '["Los estudiantes con coeficiente alto rinden mejor","Las expectativas del docente influyen en el rendimiento","Las expectativas de los padres pesan más que las del docente","La genética determina el rendimiento escolar"]'::jsonb, 1, 'Las expectativas altas o bajas del docente modifican su comportamiento hacia el estudiante, que a su vez modifica el rendimiento. Es una profecía autocumplida que el docente puede usar conscientemente.', 'exam'),
('master:steam20', 12, '¿Qué implica realmente "diferenciación pedagógica" en el aula?', '["Crear un plan de clase diferente y una evaluación distinta para cada estudiante","Ofrecer varias rutas hacia el mismo aprendizaje esencial","Separar a los estudiantes por nivel de habilidad","Dar más tarea a quienes terminan rápido"]'::jsonb, 1, 'Diferenciación no es caos ni multiplicar el trabajo. Es diseñar 2-3 rutas hacia el mismo destino de aprendizaje. Mismo objetivo, distintos caminos y ritmos.', 'exam'),
('master:steam20', 13, 'Un docente quiere integrar STEAM y ABP en una misma unidad. El primer paso correcto es:', '["Buscar materiales en internet sobre STEAM","Definir un problema auténtico de la comunidad","Pedir a los estudiantes que elijan el tema","Organizar los grupos de trabajo y repartir los roles antes de elegir el tema"]'::jsonb, 1, 'La convergencia de STEAM y ABP comienza siempre con un problema auténtico bien formulado. Sin ese ancla, la integración disciplinar queda forzada.', 'exam'),
('master:steam20', 14, 'Cuando un docente aplica Design Thinking para diseñar una rúbrica, está usando la metodología para:', '["Presentar la rúbrica de forma más atractiva para los estudiantes","Empatizar con los estudiantes para crear criterios que realmente guíen el aprendizaje, no solo califiquen","Reducir el tiempo de corrección","Cumplir con el requerimiento administrativo"]'::jsonb, 1, 'Design Thinking aplicado a la evaluación parte de la empatía: ¿qué necesita el estudiante saber para mejorar? Eso transforma una rúbrica de instrumento de control a herramienta de aprendizaje.', 'exam'),
('master:steam20', 15, 'La relación entre conocer los perfiles de aprendizaje (Tipos de Estudiantes) y ABP es que:', '["Son metodologías que se aplican en momentos distintos del año","Permite asignar roles según las fortalezas reales de cada estudiante","Los perfiles importan en la evaluación final, no al diseñar el proyecto","El ABP reemplaza la necesidad de conocer a los estudiantes"]'::jsonb, 1, 'El ABP es más poderoso cuando los roles del proyecto se asignan considerando las fortalezas de cada perfil. Por ejemplo, quien explica con claridad puede liderar la presentación, y quien es hábil construyendo, el prototipo — según fortalezas observadas, no etiquetas de "estilo".', 'exam'),
('master:steam20', 16, 'Un docente del siglo XXI integra metodologías innovadoras porque:', '["Las autoridades lo piden en las nuevas normas","Las investigaciones muestran que el aprendizaje activo, contextualizado y diferenciado produce comprensión más profunda y duradera","Es más sencillo que la enseñanza tradicional","Los estudiantes lo piden en las encuestas"]'::jsonb, 1, 'La base es investigativa, no de moda. Décadas de neurociencia y pedagogía confirman que aprender haciendo, en contexto real, con retroalimentación oportuna, produce aprendizaje que dura.', 'exam'),
('master:steam20', 17, '¿Cuál es el hilo conductor que conecta STEAM, ABP, Design Thinking y Evaluación Formativa?', '["Todos usan tecnología digital","Todos centran el aprendizaje en el estudiante, parten de problemas reales y evalúan competencias, no solo contenidos","Todos requieren laboratorios o talleres especializados","Todos se evalúan con un producto final"]'::jsonb, 1, 'El paradigma de aprendizaje activo, centrado en el estudiante y orientado a competencias es la raíz común. Son metodologías distintas de una misma visión educativa del siglo XXI.', 'exam'),
('master:steam20', 18, 'En un proyecto integrador, la evaluación más auténtica mide:', '["Cuánto memorizó el estudiante","Aplicar varias disciplinas para resolver un problema real","La calidad visual del producto final","Si siguió las instrucciones exactas del docente en cada etapa del proyecto"]'::jsonb, 1, 'La evaluación auténtica pide al estudiante que haga lo que haría un profesional: resolver problemas reales con los conocimientos adquiridos. Eso es transferencia de aprendizaje.', 'exam'),
('master:steam20', 19, 'Cuando un docente diseña una experiencia de aprendizaje con STEAM, ¿qué pregunta debe hacerse primero?', '["¿Qué actividad es más entretenida?","¿Qué problema real del contexto de mis estudiantes puedo usar para que integren ciencia, arte, matemáticas y tecnología de forma significativa?","¿Qué materiales tengo disponibles?","¿Cuánto tiempo me toma preparar esto?"]'::jsonb, 1, 'El diseño pedagógico STEAM empieza por el problema auténtico, no por el recurso ni la actividad. El contexto real del estudiante es el punto de partida.', 'exam'),
('master:steam20', 20, 'La metacognición en el estudiante se desarrolla mejor cuando:', '["El docente da retroalimentación detallada al final del semestre","Reflexiona a menudo sobre qué aprendió, cómo y qué le falta","El estudiante practica muchos exámenes de prueba","El docente corrige todos los errores de inmediato"]'::jsonb, 1, 'La metacognición requiere práctica reflexiva regular. "¿Qué aprendí hoy? ¿Cómo lo aprendí? ¿Qué me cuesta?" son preguntas que, repetidas, forman estudiantes autorregulados.', 'exam'),
('master:steam20', 21, 'Un ambiente de aula que favorece la innovación pedagógica tiene como característica fundamental:', '["Silencio total para concentrarse","Confianza para intentar, equivocarse y preguntar sin miedo","Competencia constante entre estudiantes por las mejores notas del grupo","Reglas muy estrictas de comportamiento"]'::jsonb, 1, 'La seguridad psicológica (Amy Edmondson) es la condición base para el aprendizaje profundo, la creatividad y la colaboración. Sin ella, los estudiantes se protegen en lugar de arriesgarse a aprender.', 'exam'),
('master:steam20', 22, 'La educación del siglo XXI prioriza en sus graduados:', '["Dominio enciclopédico de hechos y fechas","Capacidad de aprender, desaprender y reaprender; pensamiento crítico, colaboración, comunicación y creatividad (las 4C)","Obediencia y seguimiento de instrucciones","Especialización temprana en una sola disciplina"]'::jsonb, 1, 'En un mundo donde el conocimiento se duplica cada 2 años, la capacidad de aprender continuamente vale más que cualquier contenido específico. Las 4C son las competencias que perduran.', 'exam'),
('master:steam20', 23, 'Un docente que aplica retroalimentación formativa efectiva:', '["Espera el examen final para decir qué estuvo mal","Da comentarios específicos cuando aún sirven para mejorar","Corrige con una nota y una marca en cada error","Prefiere la retroalimentación grupal para ahorrar tiempo de corrección"]'::jsonb, 1, 'La retroalimentación efectiva tiene tres condiciones: específica (qué exactamente), oportuna (cuando aún sirve) y accionable (qué puede hacer el estudiante para mejorar). Sin las tres, pierde su poder.', 'exam'),
('master:steam20', 24, 'El portafolio de aprendizaje como herramienta de evaluación es valioso porque:', '["Permite calificar el trabajo de todo un periodo con una sola nota","Muestra la evolución del pensamiento del estudiante a lo largo del tiempo y desarrolla la capacidad de seleccionar y reflexionar sobre su propio trabajo","Reemplaza todos los demás tipos de evaluación","Permite mostrar a la familia los mejores trabajos del año"]'::jsonb, 1, 'El portafolio captura algo que ningún examen puede: el proceso de crecimiento. Al seleccionar qué incluir y por qué, el estudiante ejercita juicio y metacognición.', 'exam'),
('master:steam20', 25, 'Integrar las inteligencias múltiples de Gardner en la planificación significa:', '["Identificar la inteligencia dominante de cada estudiante y enseñarle por esa vía","Ofrecer múltiples entradas al mismo concepto — visual, verbal, kinestésica, musical — para que más estudiantes lo comprendan","Etiquetar a cada estudiante con su tipo de inteligencia","Hacer actividades diferentes para cada grupo de inteligencia"]'::jsonb, 1, 'Gardner no propone etiquetar ni separar. Propone que el mismo concepto se pueda abordar desde múltiples representaciones, ampliando el acceso al aprendizaje para más estudiantes.', 'exam'),
('master:steam20', 26, '¿Qué papel juega el error en una pedagogía innovadora?', '["El error es señal de que el estudiante no estudió suficiente","El error es información valiosa sobre el proceso de aprendizaje y punto de partida para la retroalimentación","El error debe evitarse en lo posible para no reforzarlo","El error importa sobre todo en materias como matemáticas"]'::jsonb, 1, 'En neurociencia del aprendizaje, el error activa exactamente los circuitos cerebrales necesarios para la consolidación. Un aula que teme el error, suprime el aprendizaje profundo.', 'exam'),
('master:steam20', 27, 'La colaboración efectiva en el aula (trabajo en equipo auténtico) requiere:', '["Que el más hábil haga la mayor parte del trabajo","Que cada miembro necesite a los demás para lograr la meta","Que todos hagan exactamente lo mismo","Competencia entre grupos para motivar la productividad de cada integrante"]'::jsonb, 1, 'La interdependencia positiva (Johnson & Johnson) es la condición que transforma grupos en equipos. Si un miembro puede "desconectarse" sin afectar el resultado, no hay colaboración real.', 'exam'),
('master:steam20', 28, 'Un docente reflexivo del siglo XXI se diferencia porque:', '["Aplica las mismas estrategias durante toda su carrera porque le funcionan","Observa sistemáticamente el efecto de su enseñanza en el aprendizaje real de sus estudiantes y ajusta su práctica basándose en evidencia","Reflexiona al final del año escolar sobre lo que salió bien","Delega la reflexión pedagógica a los coordinadores académicos"]'::jsonb, 1, 'La práctica reflexiva (Schön) es el hábito que separa a los docentes que mejoran de los que se estancan. Observar, analizar, ajustar — ciclo continuo, no evento anual.', 'exam'),
('master:steam20', 29, 'La pregunta más importante que un docente del siglo XXI puede hacerse al planificar es:', '["¿Cuántos contenidos puedo cubrir esta semana?","¿Qué evidencia me mostrará que mis estudiantes realmente comprendieron y pueden aplicar lo que enseñé?","¿Cómo termino el programa antes del examen nacional?","¿Qué actividad ocupa mejor el tiempo de clase?"]'::jsonb, 1, 'Planificar desde la evidencia (diseño hacia atrás, Wiggins & McTighe) garantiza que la enseñanza tenga foco real. La cobertura de contenidos sin comprensión profunda es movimiento sin aprendizaje.', 'exam'),
('master:steam20', 30, 'El aprendizaje socioemocional (SEL) en el aula importa para la innovación pedagógica porque:', '["Las emociones interfieren con el aprendizaje cognitivo","Las investigaciones muestran que la regulación emocional, la empatía y las relaciones positivas son condiciones que habilitan el aprendizaje cognitivo profundo","El SEL es responsabilidad del psicólogo, no del docente de área","El SEL mejora la convivencia, aunque no influye en el aprendizaje académico"]'::jsonb, 1, 'Neurocientíficamente, el aprendizaje ocurre cuando el cerebro está en estado de apertura, no de amenaza. El SEL crea las condiciones emocionales para que el aprendizaje cognitivo sea posible.', 'exam'),
('master:steam20', 31, 'Cuando un docente adapta su metodología según las necesidades emergentes del grupo, está practicando:', '["Diferenciación planificada desde el inicio","Enseñanza responsiva, según la evidencia que observa","Falta de planificación","Una excepción que no debe repetirse, porque rompe la planificación del periodo"]'::jsonb, 1, 'La enseñanza responsiva es la expresión práctica de la evaluación formativa. El plan es el punto de partida, no la camisa de fuerza. Los docentes expertos se desvían del plan cuando la evidencia lo justifica.', 'exam'),
('master:steam20', 32, 'La equidad educativa en el aula innovadora significa:', '["Dar exactamente lo mismo a todos los estudiantes","Dar a cada quien lo que necesita para lograr las mismas metas","Bajar las expectativas para los estudiantes con dificultades para que puedan aprobar","Dar más recursos a quienes rinden más"]'::jsonb, 1, 'Equidad no es igualdad: es justicia. Dar lo mismo a quien necesita más es perpetuar la desigualdad. La diferenciación pedagógica es la herramienta de equidad por excelencia.', 'exam'),
('master:steam20', 33, '¿Qué define al "Docente del Siglo XXI" por encima de dominar metodologías específicas?', '["Saber usar herramientas digitales avanzadas","La disposición permanente a aprender, experimentar, reflexionar y adaptar su práctica en función del aprendizaje real de sus estudiantes","Tener un máster o posgrado en educación","Seguir exactamente los programas curriculares oficiales"]'::jsonb, 1, 'Las metodologías cambian; la mentalidad de aprendizaje permanente no. El docente del siglo XXI no es quien domina las últimas técnicas, sino quien nunca deja de aprender de su propia práctica y de sus estudiantes.', 'exam')
